function normalizePromptSeed(text) {
  return String(text || "")
    .replace(/\s+/g, " ")
    .trim();
}

function dedupeSeedBanks(rawBanks, { globalUnique = true } = {}) {
  const input = rawBanks && typeof rawBanks === "object" ? rawBanks : {};
  const output = {};
  const globalSeen = new Set();
  const removed = [];

  for (const [bankKey, entries] of Object.entries(input)) {
    const list = Array.isArray(entries) ? entries : [];
    const localSeen = new Set();
    const cleaned = [];
    let localRemoved = 0;
    let globalRemoved = 0;

    for (const raw of list) {
      const seed = normalizePromptSeed(raw);
      if (!seed) continue;
      if (localSeen.has(seed)) {
        localRemoved += 1;
        continue;
      }
      if (globalUnique && globalSeen.has(seed)) {
        globalRemoved += 1;
        continue;
      }
      localSeen.add(seed);
      globalSeen.add(seed);
      cleaned.push(seed);
    }

    if (localRemoved > 0 || globalRemoved > 0) {
      removed.push({ bankKey, localRemoved, globalRemoved });
    }
    output[bankKey] = Object.freeze(cleaned);
  }

  if (removed.length) {
    const summary = removed
      .map((x) => `${x.bankKey}(local:${x.localRemoved},global:${x.globalRemoved})`)
      .join(" | ");
    console.log(`[seed_bank] dedupe removed duplicates -> ${summary}`);
  }

  return Object.freeze(output);
}

