function normalizeEmailAddress(value) {
  const raw = String(value || "")
    .trim()
    .replace(/[<>\(\)\[\],;:"']/g, "")
    .toLowerCase();
  if (!raw) return "";
  return /^[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}$/.test(raw) ? raw : "";
}

function normalizeTaskPriority(value) {
  const raw = String(value || "").trim().toLowerCase();
  if (raw === "high" || raw === "urgent") return "high";
  if (raw === "low") return "low";
  return "normal";
}

function sanitizeTaskItems(items, maxItems = TASKS_MAX_STORED) {
  const source = Array.isArray(items) ? items : [];
  const out = [];
  for (const item of source) {
    if (!item || typeof item !== "object") continue;
    const id = String(item.id || "").trim() || `task-${randomUUID().slice(0, 8)}`;
    const title = normalizeSnippet(item.title, 160);
    if (!title) continue;
    const statusRaw = String(item.status || "open").trim().toLowerCase();
    const status = statusRaw === "done" || statusRaw === "completed" ? "completed" : "open";
    const priority = normalizeTaskPriority(item.priority);
    const dueAt = Math.max(0, Number(item.dueAt || 0));
    const createdAt = Math.max(0, Number(item.createdAt || 0));
    const completedAt = Math.max(0, Number(item.completedAt || 0));
    const sourceTag = normalizeSnippet(item.source, 40) || "conversation";
    out.push({
      id,
      title,
      status,
      priority,
      dueAt,
      createdAt,
      completedAt,
      source: sourceTag,
    });
  }
  return out.slice(-Math.max(1, maxItems));
}

function parseSimpleDueAt(text, nowTs = Date.now()) {
  const source = String(text || "").toLowerCase();
  if (!source) return 0;
  const now = new Date(nowTs);
  const base = new Date(now.getFullYear(), now.getMonth(), now.getDate(), 9, 0, 0, 0);

  if (source.includes("tomorrow")) {
    base.setDate(base.getDate() + 1);
  } else if (source.includes("tonight")) {
    base.setHours(20, 0, 0, 0);
  } else {
    const weekdayMap = {
      sunday: 0,
      monday: 1,
      tuesday: 2,
      wednesday: 3,
      thursday: 4,
      friday: 5,
      saturday: 6,
    };
    const weekdayMatch = source.match(/\b(sunday|monday|tuesday|wednesday|thursday|friday|saturday)\b/);
    if (weekdayMatch) {
      const target = weekdayMap[String(weekdayMatch[1] || "").toLowerCase()];
      if (Number.isFinite(target)) {
        const current = now.getDay();
        let delta = (target - current + 7) % 7;
        if (delta === 0) delta = 7;
        base.setDate(base.getDate() + delta);
      }
    }
  }

  const timeMatch = source.match(/\b(\d{1,2})(?::(\d{2}))?\s*(am|pm)\b/);
  if (timeMatch) {
    let hour = Number(timeMatch[1] || 9);
    const minute = Math.max(0, Math.min(59, Number(timeMatch[2] || 0)));
    const suffix = String(timeMatch[3] || "").toLowerCase();
    if (suffix === "pm" && hour < 12) hour += 12;
    if (suffix === "am" && hour === 12) hour = 0;
    hour = Math.max(0, Math.min(23, hour));
    base.setHours(hour, minute, 0, 0);
  }

  return base.getTime();
}

function extractTaskCandidatesFromText(text, maxItems = 6) {
  const source = String(text || "").trim();
  if (!source) return [];
  const normalized = source
    .replace(/\n+/g, ",")
    .replace(/\band\b/gi, ",")
    .split(",")
    .map((part) => normalizeSnippet(part, 160))
    .filter(Boolean)
    .map((part) => part.replace(/^[-*\d.\)\s]+/, "").trim())
    .filter(Boolean);

  const candidates = [];
  for (const part of normalized) {
    if (candidates.length >= maxItems) break;
    if (part.length < 4) continue;
    candidates.push(part);
  }
  return candidates;
}

function extractTaskCreateIntent(transcript) {
  const source = String(transcript || "").trim();
  if (!source) {
    return { shouldCreate: false, title: "", dueAt: 0, priority: "normal", trigger: "" };
  }
  const lower = source.toLowerCase();
  const triggers = [
    "remind me to",
    "create a task",
    "add a task",
    "new task",
    "todo",
    "to do",
    "add this task",
  ];
  let trigger = "";
  let triggerIndex = -1;
  for (const candidate of triggers) {
    const idx = lower.indexOf(candidate);
    if (idx >= 0 && (triggerIndex === -1 || idx < triggerIndex)) {
      trigger = candidate;
      triggerIndex = idx;
    }
  }
  if (triggerIndex < 0) {
    return { shouldCreate: false, title: "", dueAt: 0, priority: "normal", trigger: "" };
  }

  let title = source
    .slice(triggerIndex + trigger.length)
    .replace(/^[\s:,\-–—]+/, "")
    .trim();
  title = title.replace(/^to\s+/i, "").trim();
  title = normalizeSnippet(title, 160);
  if (!title) {
    return { shouldCreate: false, title: "", dueAt: 0, priority: "normal", trigger };
  }

  const priority = lower.includes("urgent") || lower.includes("asap") || lower.includes("high priority")
    ? "high"
    : (lower.includes("low priority") ? "low" : "normal");

  return {
    shouldCreate: true,
    title,
    dueAt: parseSimpleDueAt(source),
    priority: normalizeTaskPriority(priority),
    trigger,
  };
}

function extractTaskCompleteIntent(transcript) {
  const source = String(transcript || "").trim();
  if (!source) {
    return { shouldComplete: false, query: "", trigger: "" };
  }
  const lower = source.toLowerCase();
  const triggers = [
    "mark task done",
    "mark it done",
    "mark this done",
    "check this off",
    "check it off",
    "complete task",
    "complete this task",
    "task done",
    "i finished that task",
    "i finished this task",
  ];
  let trigger = "";
  let triggerIndex = -1;
  for (const candidate of triggers) {
    const idx = lower.indexOf(candidate);
    if (idx >= 0 && (triggerIndex === -1 || idx < triggerIndex)) {
      trigger = candidate;
      triggerIndex = idx;
    }
  }
  if (triggerIndex < 0) {
    return { shouldComplete: false, query: "", trigger: "" };
  }
  let query = source
    .slice(triggerIndex + trigger.length)
    .replace(/^[\s:,\-–—]+/, "")
    .trim();
  query = normalizeSnippet(query, 160);
  return {
    shouldComplete: true,
    query,
    trigger,
  };
}

function createTaskInMemory(memory, { title, dueAt = 0, priority = "normal", source = "conversation" }, nowTs = Date.now()) {
  if (!memory || typeof memory !== "object") return null;
  const cleanTitle = normalizeSnippet(title, 160);
  if (!cleanTitle) return null;
  const tasks = sanitizeTaskItems(memory.tasks, TASKS_MAX_STORED);
  const existing = tasks.find(
    (item) => item.status === "open" && item.title.toLowerCase() === cleanTitle.toLowerCase()
  );
  if (existing) return { ...existing, duplicate: true };
  const task = {
    id: `task-${randomUUID().slice(0, 10)}`,
    title: cleanTitle,
    status: "open",
    priority: normalizeTaskPriority(priority),
    dueAt: Math.max(0, Number(dueAt || 0)),
    createdAt: nowTs,
    completedAt: 0,
    source: normalizeSnippet(source, 40) || "conversation",
  };
  tasks.push(task);
  memory.tasks = sanitizeTaskItems(tasks, TASKS_MAX_STORED);
  memory.taskLastUpdatedAt = nowTs;
  return task;
}

function completeTaskInMemory(memory, query = "", nowTs = Date.now()) {
  if (!memory || typeof memory !== "object") return null;
  const tasks = sanitizeTaskItems(memory.tasks, TASKS_MAX_STORED);
  if (!tasks.length) return null;
  const normalizedQuery = String(query || "").trim().toLowerCase();
  let target = null;
  if (normalizedQuery) {
    target = tasks.find(
      (item) =>
        item.status === "open" &&
        (item.id.toLowerCase() === normalizedQuery || item.title.toLowerCase().includes(normalizedQuery))
    );
  }
  if (!target) {
    target = [...tasks].reverse().find((item) => item.status === "open") || null;
  }
  if (!target) return null;
  const updated = tasks.map((item) => {
    if (item.id !== target.id) return item;
    return {
      ...item,
      status: "completed",
      completedAt: nowTs,
    };
  });
  memory.tasks = sanitizeTaskItems(updated, TASKS_MAX_STORED);
  memory.taskLastUpdatedAt = nowTs;
  return { ...target, status: "completed", completedAt: nowTs };
}

function reopenTaskInMemory(memory, query = "", nowTs = Date.now()) {
  if (!memory || typeof memory !== "object") return null;
  const tasks = sanitizeTaskItems(memory.tasks, TASKS_MAX_STORED);
  if (!tasks.length) return null;
  const normalizedQuery = String(query || "").trim().toLowerCase();
  let target = null;
  if (normalizedQuery) {
    target = tasks.find(
      (item) =>
        item.status === "completed" &&
        (item.id.toLowerCase() === normalizedQuery || item.title.toLowerCase().includes(normalizedQuery))
    );
  }
  if (!target) {
    target = [...tasks].reverse().find((item) => item.status === "completed") || null;
  }
  if (!target) return null;
  const updated = tasks.map((item) => {
    if (item.id !== target.id) return item;
    return {
      ...item,
      status: "open",
      completedAt: 0,
    };
  });
  memory.tasks = sanitizeTaskItems(updated, TASKS_MAX_STORED);
  memory.taskLastUpdatedAt = nowTs;
  return { ...target, status: "open", completedAt: 0 };
}

function deleteTaskInMemory(memory, query = "", nowTs = Date.now()) {
  if (!memory || typeof memory !== "object") return null;
  const tasks = sanitizeTaskItems(memory.tasks, TASKS_MAX_STORED);
  if (!tasks.length) return null;
  const normalizedQuery = String(query || "").trim().toLowerCase();
  let target = null;
  if (normalizedQuery) {
    target = tasks.find(
      (item) =>
        item.id.toLowerCase() === normalizedQuery ||
        item.title.toLowerCase().includes(normalizedQuery)
    );
  }
  if (!target) {
    target = tasks[tasks.length - 1] || null;
  }
  if (!target) return null;
  const updated = tasks.filter((item) => item.id !== target.id);
  memory.tasks = sanitizeTaskItems(updated, TASKS_MAX_STORED);
  memory.taskLastUpdatedAt = nowTs;
  return target;
}

function clearCompletedTasksInMemory(memory, nowTs = Date.now()) {
  if (!memory || typeof memory !== "object") return 0;
  const tasks = sanitizeTaskItems(memory.tasks, TASKS_MAX_STORED);
  const remaining = tasks.filter((item) => item.status !== "completed");
  const removedCount = Math.max(0, tasks.length - remaining.length);
  if (!removedCount) return 0;
  memory.tasks = sanitizeTaskItems(remaining, TASKS_MAX_STORED);
  memory.taskLastUpdatedAt = nowTs;
  return removedCount;
}

function buildTaskActionReply(result) {
  const state = result && typeof result === "object" ? result : {};
  if (state.status === "needs_confirmation") {
    return buildPendingLocalActionConfirmationReply({
      summary: state.summary || "",
    });
  }
  if (state.status === "created") {
    const due = Number(state.task?.dueAt || 0) > 0
      ? ` due ${new Date(Number(state.task.dueAt)).toLocaleString()}`
      : "";
    return [
      "Done.",
      "",
      `I added this task: "${state.task?.title || "task"}"${due}.`,
    ].join("\n");
  }
  if (state.status === "completed") {
    return [
      "Nice.",
      "",
      `Marked complete: "${state.task?.title || "task"}".`,
    ].join("\n");
  }
  if (state.status === "duplicate") {
    return [
      "Already tracked.",
      "",
      `You already have an open task for "${state.task?.title || "that"}".`,
    ].join("\n");
  }
  if (state.status === "none") {
    return [
      "I could not find an open task to complete.",
      "",
      "Say the task name and I will mark it done.",
    ].join("\n");
  }
  if (state.status === "failed") {
    return [
      "I could not update that task yet.",
      "",
      "Say it one more time with the task name.",
    ].join("\n");
  }
  return "";
}

function parseCalendarRange(transcript, nowTs = Date.now()) {
  const source = String(transcript || "").toLowerCase();
  const now = new Date(nowTs);
  const base = new Date(now.getFullYear(), now.getMonth(), now.getDate(), 9, 0, 0, 0);
  if (source.includes("tomorrow")) {
    base.setDate(base.getDate() + 1);
  }

  const rangeMatch = source.match(
    /\b(\d{1,2})(?::(\d{2}))?\s*(am|pm)?\s*(?:to|-|until)\s*(\d{1,2})(?::(\d{2}))?\s*(am|pm)?\b/
  );
  if (!rangeMatch) {
    return {
      startAt: base.getTime(),
      endAt: base.getTime() + (60 * 60 * 1000),
    };
  }

  const parseHour = (hourRaw, minuteRaw, meridiemRaw, fallbackMeridiem = "") => {
    let hour = Math.max(0, Math.min(23, Number(hourRaw || 9)));
    const minute = Math.max(0, Math.min(59, Number(minuteRaw || 0)));
    const meridiem = String(meridiemRaw || fallbackMeridiem || "").toLowerCase();
    if (meridiem === "pm" && hour < 12) hour += 12;
    if (meridiem === "am" && hour === 12) hour = 0;
    return { hour, minute };
  };

  const startMeridiem = rangeMatch[3] || rangeMatch[6] || "";
  const endMeridiem = rangeMatch[6] || rangeMatch[3] || "";
  const startParts = parseHour(rangeMatch[1], rangeMatch[2], startMeridiem, endMeridiem);
  const endParts = parseHour(rangeMatch[4], rangeMatch[5], endMeridiem, startMeridiem);

  const start = new Date(base);
  start.setHours(startParts.hour, startParts.minute, 0, 0);
  const end = new Date(base);
  end.setHours(endParts.hour, endParts.minute, 0, 0);
  if (end.getTime() <= start.getTime()) {
    end.setTime(start.getTime() + (60 * 60 * 1000));
  }
  return { startAt: start.getTime(), endAt: end.getTime() };
}

function extractCalendarIntent(transcript) {
  const source = String(transcript || "").trim();
  if (!source) {
    return { shouldCreate: false, title: "", startAt: 0, endAt: 0, trigger: "" };
  }
  const lower = source.toLowerCase();
  const triggers = [
    "schedule",
    "calendar",
    "block",
    "set a meeting",
    "create event",
    "book time",
  ];
  let trigger = "";
  let triggerIndex = -1;
  for (const candidate of triggers) {
    const idx = lower.indexOf(candidate);
    if (idx >= 0 && (triggerIndex === -1 || idx < triggerIndex)) {
      trigger = candidate;
      triggerIndex = idx;
    }
  }
  if (triggerIndex < 0) {
    return { shouldCreate: false, title: "", startAt: 0, endAt: 0, trigger: "" };
  }
  const range = parseCalendarRange(source);
  let title = source
    .slice(triggerIndex + trigger.length)
    .replace(/^[\s:,\-–—]+/, "")
    .replace(/\b(today|tomorrow|tonight)\b/gi, "")
    .replace(/\b\d{1,2}(?::\d{2})?\s*(am|pm)?\s*(to|-|until)\s*\d{1,2}(?::\d{2})?\s*(am|pm)?\b/gi, "")
    .trim();
  title = normalizeSnippet(title, 120) || "Calendar block";
  return {
    shouldCreate: true,
    title,
    startAt: range.startAt,
    endAt: range.endAt,
    trigger,
  };
}

function formatGoogleCalendarDate(ts) {
  return new Date(ts).toISOString().replace(/[-:]/g, "").replace(/\.\d{3}Z$/, "Z");
}

function buildCalendarComposeUrl({ title, startAt, endAt, details = "", target = CALENDAR_COMPOSE_TARGET }) {
  const safeTitle = normalizeSnippet(title, 120) || "Calendar block";
  const safeDetails = normalizeSnippet(details, 400);
  const normalizedTarget = parseOneOf(String(target || "google"), CALENDAR_COMPOSE_TARGETS, "google");
  if (normalizedTarget === "outlook") {
    const outlook = new URL("https://outlook.live.com/calendar/0/deeplink/compose");
    outlook.searchParams.set("path", "/calendar/action/compose");
    outlook.searchParams.set("rru", "addevent");
    outlook.searchParams.set("subject", safeTitle);
    outlook.searchParams.set("startdt", new Date(startAt).toISOString());
    outlook.searchParams.set("enddt", new Date(endAt).toISOString());
    if (safeDetails) outlook.searchParams.set("body", safeDetails);
    return { url: outlook.toString(), target: "outlook", transport: "browser" };
  }
  if (normalizedTarget === "ics") {
    const lines = [
      "BEGIN:VCALENDAR",
      "VERSION:2.0",
      "PRODID:-//CLEMENTINE//EN",
      "BEGIN:VEVENT",
      `UID:${randomUUID()}`,
      `DTSTAMP:${formatGoogleCalendarDate(Date.now())}`,
      `DTSTART:${formatGoogleCalendarDate(startAt)}`,
      `DTEND:${formatGoogleCalendarDate(endAt)}`,
      `SUMMARY:${safeTitle.replace(/\n/g, " ")}`,
      `DESCRIPTION:${(safeDetails || "Created by CLEMENTINE").replace(/\n/g, "\\n")}`,
      "END:VEVENT",
      "END:VCALENDAR",
    ].join("\r\n");
    return {
      url: `data:text/calendar;charset=utf-8,${encodeURIComponent(lines)}`,
      target: "ics",
      transport: "file",
    };
  }
  const google = new URL("https://calendar.google.com/calendar/render");
  google.searchParams.set("action", "TEMPLATE");
  google.searchParams.set("text", safeTitle);
  google.searchParams.set("dates", `${formatGoogleCalendarDate(startAt)}/${formatGoogleCalendarDate(endAt)}`);
  if (safeDetails) google.searchParams.set("details", safeDetails);
  return { url: google.toString(), target: "google", transport: "browser" };
}

function buildCalendarActionReply(result) {
  const state = result && typeof result === "object" ? result : {};
  if (state.status === "needs_confirmation") {
    return buildPendingLocalActionConfirmationReply({
      summary: state.summary || "",
    });
  }
  if (state.status === "composed") {
    return [
      "Done.",
      "",
      `I opened a calendar draft for "${state.title || "your block"}".`,
    ].join("\n");
  }
  if (state.status === "failed") {
    return [
      "I could not open that calendar draft yet.",
      "",
      "Say the title and time again and I will retry.",
    ].join("\n");
  }
  return "";
}

function classifyActionLane({ emailResult, noteResult, calendarResult, taskResult }) {
  if (emailResult) {
    return { lane: "email_draft", created: emailResult.status === "composed" };
  }
  if (calendarResult) {
    return { lane: "calendar_block", created: calendarResult.status === "composed" };
  }
  if (taskResult) {
    return {
      lane: "task",
      created: new Set(["created", "completed", "reopened", "deleted", "cleared_completed", "duplicate"])
        .has(String(taskResult.status || "")),
    };
  }
  if (noteResult) {
    return { lane: "note", created: noteResult.status === "saved" };
  }
  return { lane: "chat", created: false };
}

function buildCapturedEmailSubject(bodyText) {
  const cleaned = String(bodyText || "")
    .replace(/\s+/g, " ")
    .replace(/^[\s"'`]+|[\s"'`]+$/g, "")
    .trim();
  if (!cleaned) return "Message from CLEMENTINE";
  const sentence = cleaned.split(/[.!?]/)[0] || cleaned;
  return trimToMax(sentence, 84);
}

function extractEmailSendIntent(transcript) {
  const source = String(transcript || "").trim();
  if (!source) {
    return {
      shouldSend: false,
      needsRecipient: false,
      needsContent: false,
      trigger: "",
      recipient: "",
      subject: "",
      body: "",
    };
  }

  const lower = source.toLowerCase();
  let trigger = "";
  let triggerIndex = -1;
  for (const candidate of EMAIL_SEND_TRIGGERS) {
    const idx = lower.indexOf(candidate);
    if (idx >= 0 && (triggerIndex === -1 || idx < triggerIndex)) {
      trigger = candidate;
      triggerIndex = idx;
    }
  }

  if (triggerIndex < 0) {
    return {
      shouldSend: false,
      needsRecipient: false,
      needsContent: false,
      trigger: "",
      recipient: "",
      subject: "",
      body: "",
    };
  }

  let working = source
    .slice(triggerIndex + trigger.length)
    .replace(/^[\s:,\-–—]+/, "")
    .trim();

  const emailMatch = (working.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i) ||
    source.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i));
  const recipient = normalizeEmailAddress(emailMatch?.[0] || "");
  if (recipient) {
    working = working.replace(new RegExp(escapeRegex(emailMatch[0]), "i"), "").trim();
  }

  let subject = "";
  let body = "";
  const subjectMarker = working.match(/\bsubject\b[:\s-]*/i);
  const bodyMarker = working.match(/\b(?:body|message|saying|that says)\b[:\s-]*/i);

  if (subjectMarker) {
    const subjectStart = subjectMarker.index + subjectMarker[0].length;
    if (bodyMarker && bodyMarker.index > subjectStart) {
      subject = working.slice(subjectStart, bodyMarker.index).trim();
      body = working.slice(bodyMarker.index + bodyMarker[0].length).trim();
    } else {
      subject = working.slice(subjectStart).trim();
    }
  } else if (bodyMarker) {
    body = working.slice(bodyMarker.index + bodyMarker[0].length).trim();
  } else {
    body = working;
  }

  body = String(body || "")
    .replace(/^["“”'`]+|["“”'`]+$/g, "")
    .replace(/\s+/g, " ")
    .trim();
  subject = String(subject || "")
    .replace(/^["“”'`]+|["“”'`]+$/g, "")
    .replace(/\s+/g, " ")
    .trim();
  if (!subject) {
    subject = buildCapturedEmailSubject(body);
  }

  return {
    shouldSend: true,
    needsRecipient: !recipient,
    needsContent: !body || body.length < 3,
    trigger,
    recipient,
    subject: trimToMax(subject, 120),
    body,
  };
}

function clearPendingEmailDraft(memory, nowTs = Date.now()) {
  if (!memory || typeof memory !== "object") return;
  memory.pendingEmailRecipient = "";
  memory.pendingEmailSubject = "";
  memory.pendingEmailAwaitingBody = false;
  memory.pendingEmailUpdatedAt = Math.max(0, Number(nowTs || Date.now()));
}

function setPendingEmailDraft(memory, { recipient, subject }, nowTs = Date.now()) {
  if (!memory || typeof memory !== "object") return;
  memory.pendingEmailRecipient = normalizeEmailAddress(recipient);
  memory.pendingEmailSubject = trimToMax(String(subject || "").trim(), 120);
  memory.pendingEmailAwaitingBody = Boolean(memory.pendingEmailRecipient);
  memory.pendingEmailUpdatedAt = Math.max(0, Number(nowTs || Date.now()));
}

function readPendingEmailDraft(memory) {
  if (!memory || typeof memory !== "object") {
    return {
      recipient: "",
      subject: "",
      awaitingBody: false,
      updatedAt: 0,
    };
  }
  const recipient = normalizeEmailAddress(memory.pendingEmailRecipient);
  const subject = trimToMax(String(memory.pendingEmailSubject || "").trim(), 120);
  const updatedAt = Math.max(0, Number(memory.pendingEmailUpdatedAt || 0));
  const awaitingBody = Boolean(memory.pendingEmailAwaitingBody) && Boolean(recipient);
  return {
    recipient,
    subject,
    awaitingBody,
    updatedAt,
  };
}

const LOCAL_ACTION_CONFIRM_TRIGGERS = Object.freeze([
  "confirm",
  "yes confirm",
  "confirm it",
  "do it",
  "go ahead",
  "proceed",
  "yes send",
  "yes do that",
  "confirm action",
]);

const LOCAL_ACTION_CANCEL_TRIGGERS = Object.freeze([
  "cancel action",
  "cancel that",
  "never mind",
  "dont do that",
  "don't do that",
  "stop that",
  "forget that",
]);

function isLocalActionConfirmationTranscript(transcript = "") {
  const t = String(transcript || "").toLowerCase().trim();
  if (!t) return false;
  return textContainsAny(t, LOCAL_ACTION_CONFIRM_TRIGGERS);
}

function isLocalActionCancelTranscript(transcript = "") {
  const t = String(transcript || "").toLowerCase().trim();
  if (!t) return false;
  return textContainsAny(t, LOCAL_ACTION_CANCEL_TRIGGERS);
}

function clearPendingLocalAction(memory, nowTs = Date.now()) {
  if (!memory || typeof memory !== "object") return;
  memory.pendingLocalActionType = "";
  memory.pendingLocalActionPayload = "";
  memory.pendingLocalActionSummary = "";
  memory.pendingLocalActionUpdatedAt = Math.max(0, Number(nowTs || Date.now()));
}

function buildPendingLocalActionSummary(type, payload = {}) {
  const actionType = normalizeLocalActionType(type);
  const body = payload && typeof payload === "object" ? payload : {};
  if (actionType === "email_compose") {
    const to = normalizeEmailAddress(body.recipient || body.to);
    const subject = trimToMax(String(body.subject || "").trim(), 80);
    return `Open email draft to ${to || "recipient"}${subject ? ` with subject "${subject}"` : ""}.`;
  }
  if (actionType === "note_capture") {
    const noteText = normalizeSnippet(body.noteText, 120);
    return `Save note: "${noteText || "your note"}".`;
  }
  if (actionType === "calendar_compose") {
    const title = normalizeSnippet(body.title, 96) || "Calendar block";
    return `Open calendar draft "${title}".`;
  }
  if (actionType === "task_create") {
    const title = normalizeSnippet(body.title, 96) || "task";
    return `Create task "${title}".`;
  }
  if (actionType === "task_complete") {
    const query = normalizeSnippet(body.query, 96) || "latest task";
    return `Mark task complete: "${query}".`;
  }
  return "Run that local action.";
}

function setPendingLocalAction(memory, { type, payload = {}, summary = "" } = {}, nowTs = Date.now()) {
  if (!memory || typeof memory !== "object") return;
  const normalizedType = normalizeLocalActionType(type);
  if (!normalizedType || normalizedType === "none") return;
  const body = payload && typeof payload === "object" ? payload : {};
  const payloadText = normalizeSnippet(JSON.stringify(body), 2_400);
  memory.pendingLocalActionType = normalizedType;
  memory.pendingLocalActionPayload = payloadText;
  memory.pendingLocalActionSummary = normalizeSnippet(
    summary || buildPendingLocalActionSummary(normalizedType, body),
    220
  );
  memory.pendingLocalActionUpdatedAt = Math.max(0, Number(nowTs || Date.now()));
}

function readPendingLocalAction(memory) {
  if (!memory || typeof memory !== "object") {
    return {
      exists: false,
      type: "",
      payload: {},
      summary: "",
      updatedAt: 0,
    };
  }
  const type = normalizeLocalActionType(memory.pendingLocalActionType);
  const summary = normalizeSnippet(memory.pendingLocalActionSummary, 220);
  const updatedAt = Math.max(0, Number(memory.pendingLocalActionUpdatedAt || 0));
  if (!type || type === "none") {
    return { exists: false, type: "", payload: {}, summary: "", updatedAt };
  }
  let payload = {};
  const payloadRaw = String(memory.pendingLocalActionPayload || "").trim();
  if (payloadRaw) {
    try {
      const parsed = JSON.parse(payloadRaw);
      if (parsed && typeof parsed === "object") payload = parsed;
    } catch (_) {
      payload = {};
    }
  }
  return {
    exists: true,
    type,
    payload,
    summary: summary || buildPendingLocalActionSummary(type, payload),
    updatedAt,
  };
}

function buildPendingLocalActionConfirmationReply(pending) {
  const p = pending && typeof pending === "object" ? pending : {};
  const summary = normalizeSnippet(p.summary, 220) || "I prepared that action.";
  return [
    "I prepared that action.",
    "",
    summary,
    "",
    "Say \"confirm\" to run it, or \"cancel action\" to stop.",
  ].join("\n");
}

function buildNoPendingLocalActionReply() {
  return [
    "There is no pending action to confirm.",
    "",
    "Tell me exactly what to do, then I will ask for confirmation.",
  ].join("\n");
}

function selectExecutableLocalActionCandidate({
  noteCaptureIntent,
  emailSendIntent,
  calendarIntent,
  taskCreateIntent,
  taskCompleteIntent,
} = {}) {
  if (noteCaptureIntent?.shouldCapture && !noteCaptureIntent?.needsContent) {
    return {
      type: "note_capture",
      payload: {
        noteText: normalizeSnippet(noteCaptureIntent.noteText, 1_600),
        trigger: normalizeSnippet(noteCaptureIntent.trigger, 64),
      },
    };
  }
  if (
    emailSendIntent?.shouldSend &&
    !emailSendIntent?.canceled &&
    !emailSendIntent?.needsRecipient &&
    !emailSendIntent?.needsContent
  ) {
    return {
      type: "email_compose",
      payload: {
        recipient: normalizeEmailAddress(emailSendIntent.recipient),
        subject: trimToMax(String(emailSendIntent.subject || "").trim(), 120),
        body: normalizeSnippet(emailSendIntent.body, EMAIL_COMPOSE_BODY_MAX_CHARS),
        trigger: normalizeSnippet(emailSendIntent.trigger, 64),
      },
    };
  }
  if (calendarIntent?.shouldCreate) {
    return {
      type: "calendar_compose",
      payload: {
        title: normalizeSnippet(calendarIntent.title, 120),
        startAt: Math.max(0, Number(calendarIntent.startAt || 0)),
        endAt: Math.max(0, Number(calendarIntent.endAt || 0)),
        trigger: normalizeSnippet(calendarIntent.trigger, 64),
      },
    };
  }
  if (taskCreateIntent?.shouldCreate) {
    return {
      type: "task_create",
      payload: {
        title: normalizeSnippet(taskCreateIntent.title, 120),
        dueAt: Math.max(0, Number(taskCreateIntent.dueAt || 0)),
        priority: normalizeSnippet(taskCreateIntent.priority, 24) || "normal",
        trigger: normalizeSnippet(taskCreateIntent.trigger, 64),
      },
    };
  }
  if (taskCompleteIntent?.shouldComplete) {
    return {
      type: "task_complete",
      payload: {
        query: normalizeSnippet(taskCompleteIntent.query, 120),
        trigger: normalizeSnippet(taskCompleteIntent.trigger, 64),
      },
    };
  }
  return null;
}

function normalizeEmailFollowupBody(text) {
  let body = String(text || "").trim();
  if (!body) return "";
  const lowered = body.toLowerCase();
  for (const hint of EMAIL_FOLLOWUP_BODY_HINTS) {
    if (lowered.startsWith(`${hint}:`) || lowered.startsWith(`${hint} `)) {
      body = body.slice(hint.length).replace(/^[:\s-]+/, "").trim();
      break;
    }
  }
  body = body.replace(/^["“”'`]+|["“”'`]+$/g, "").trim();
  return body;
}

function looksLikeOpenQuestion(text) {
  const source = String(text || "").trim().toLowerCase();
  if (!source) return false;
  if (source.endsWith("?")) return true;
  return /^(how|what|why|when|where|who|can|could|would|should|do|does|did|is|are|am)\b/.test(source);
}

function resolveEmailSendIntentWithPending({
  transcript,
  baseIntent,
  memory,
  noteCaptureIntent,
}) {
  const base = baseIntent && typeof baseIntent === "object"
    ? { ...baseIntent }
    : {
      shouldSend: false,
      needsRecipient: false,
      needsContent: false,
      trigger: "",
      recipient: "",
      subject: "",
      body: "",
    };
  if (!SECRETARY_EMAIL_FOLLOWUP_ENABLED || !memory || typeof memory !== "object") {
    return {
      ...base,
      fromPending: false,
      canceled: false,
    };
  }

  const text = String(transcript || "").trim();
  const lower = text.toLowerCase();
  const nowTs = Date.now();
  const pending = readPendingEmailDraft(memory);
  const askedCancel = textContainsAny(lower, EMAIL_CANCEL_TRIGGERS);

  if (askedCancel && pending.awaitingBody) {
    clearPendingEmailDraft(memory, nowTs);
    return {
      shouldSend: false,
      needsRecipient: false,
      needsContent: false,
      trigger: "cancel_email_pending",
      recipient: "",
      subject: "",
      body: "",
      fromPending: false,
      canceled: true,
    };
  }

  if (base.shouldSend) {
    if (!base.needsRecipient && base.needsContent && base.recipient) {
      setPendingEmailDraft(memory, {
        recipient: base.recipient,
        subject: base.subject,
      }, nowTs);
      return {
        ...base,
        fromPending: false,
        canceled: false,
      };
    }

    if (!base.needsRecipient && !base.needsContent) {
      clearPendingEmailDraft(memory, nowTs);
    }
    return {
      ...base,
      fromPending: false,
      canceled: false,
    };
  }

  if (!pending.awaitingBody) {
    return {
      ...base,
      fromPending: false,
      canceled: false,
    };
  }

  const pendingAgeMs = Math.max(0, nowTs - pending.updatedAt);
  if (pending.updatedAt && pendingAgeMs > 10 * 60 * 1000) {
    clearPendingEmailDraft(memory, nowTs);
    return {
      ...base,
      fromPending: false,
      canceled: false,
    };
  }

  if (noteCaptureIntent?.shouldCapture) {
    return {
      ...base,
      fromPending: false,
      canceled: false,
    };
  }

  if (textContainsAny(lower, ["linkedin", "profile analysis", "analyze profile"])) {
    return {
      ...base,
      fromPending: false,
      canceled: false,
    };
  }

  const normalizedBody = normalizeEmailFollowupBody(text);
  const bodyWordCount = normalizedBody.split(/\s+/).filter(Boolean).length;
  const hintedBody = EMAIL_FOLLOWUP_BODY_HINTS.some((hint) => lower.startsWith(hint));
  const explicitPendingConfirm = textContainsAny(lower, EMAIL_PENDING_FOLLOWUP_CONFIRM_TRIGGERS);
  let followupBody = normalizedBody;
  if (explicitPendingConfirm && !hintedBody) {
    followupBody = followupBody
      .replace(
        /^(?:please\s+)?(?:go ahead(?: and)?\s+)?(?:send (?:it|this|that|now)|email (?:it|this|that)|use (?:this|that) message|that(?:'|’)s the message|that is the message)\b[:\s-]*/i,
        ""
      )
      .trim();
  }
  const followupBodyWords = followupBody.split(/\s+/).filter(Boolean).length;
  if (explicitPendingConfirm && followupBodyWords < 4) {
    return {
      shouldSend: true,
      needsRecipient: false,
      needsContent: true,
      trigger: "pending_email_followup_confirmed",
      recipient: pending.recipient,
      subject: pending.subject || buildCapturedEmailSubject(""),
      body: "",
      fromPending: true,
      canceled: false,
    };
  }
  const safeToAssumeBody =
    hintedBody ||
    (
      explicitPendingConfirm &&
      !looksLikeOpenQuestion(followupBody) &&
      followupBodyWords >= 4 &&
      followupBodyWords <= 220
    );

  if (!safeToAssumeBody) {
    return {
      ...base,
      fromPending: false,
      canceled: false,
    };
  }

  return {
    shouldSend: true,
    needsRecipient: false,
    needsContent: !followupBody,
    trigger: "pending_email_followup",
    recipient: pending.recipient,
    subject: pending.subject || buildCapturedEmailSubject(followupBody),
    body: followupBody,
    fromPending: true,
    canceled: false,
  };
}

function normalizeLocalActionType(value) {
  const clean = String(value || "")
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9_]+/g, "_")
    .replace(/^_+|_+$/g, "");
  return clean || "none";
}

function buildLocalActionSignature(type, payload = {}) {
  const normalizedType = normalizeLocalActionType(type);
  const body = payload && typeof payload === "object" ? payload : {};
  const parts = Object.keys(body)
    .sort((a, b) => a.localeCompare(b))
    .map((key) => `${key}:${normalizeSnippet(body[key], 180).toLowerCase()}`);
  const raw = `${normalizedType}|${parts.join("|")}`;
  return createHash("sha1").update(raw).digest("hex").slice(0, 20);
}

function isLocalActionDuplicate(memory, {
  type = "",
  signature = "",
  nowTs = Date.now(),
  windowMs = LOCAL_ACTION_DEDUPE_WINDOW_MS,
} = {}) {
  if (!memory || typeof memory !== "object") return false;
  const lastType = normalizeLocalActionType(memory.lastLocalActionType);
  const nextType = normalizeLocalActionType(type);
  if (!nextType || nextType === "none" || !signature) return false;
  if (lastType !== nextType) return false;
  const lastSignature = String(memory.lastLocalActionSignature || "").trim();
  if (!lastSignature || lastSignature !== signature) return false;
  const lastAt = Math.max(0, Number(memory.lastLocalActionAt || 0));
  if (!lastAt) return false;
  const ageMs = Math.max(0, Number(nowTs || Date.now()) - lastAt);
  return ageMs <= Math.max(2_000, Number(windowMs || LOCAL_ACTION_DEDUPE_WINDOW_MS));
}

function recordLocalAction(memory, {
  type = "",
  signature = "",
  nowTs = Date.now(),
} = {}) {
  if (!memory || typeof memory !== "object") return;
  const nextType = normalizeLocalActionType(type);
  if (!nextType || nextType === "none" || !signature) return;
  memory.lastLocalActionType = nextType;
  memory.lastLocalActionSignature = String(signature || "").trim();
  memory.lastLocalActionAt = Math.max(0, Number(nowTs || Date.now()));
}

function extractNoteCaptureIntent(transcript) {
  const source = String(transcript || "").trim();
  if (!source) {
    return {
      shouldCapture: false,
      needsContent: false,
      noteText: "",
      trigger: "",
    };
  }

  const lower = source.toLowerCase();
  let trigger = "";
  let triggerIndex = -1;

  for (const candidate of NOTE_CAPTURE_TRIGGERS) {
    const idx = lower.indexOf(candidate);
    if (idx >= 0 && (triggerIndex === -1 || idx < triggerIndex)) {
      trigger = candidate;
      triggerIndex = idx;
    }
  }

  if (triggerIndex < 0) {
    return {
      shouldCapture: false,
      needsContent: false,
      noteText: "",
      trigger: "",
    };
  }

  let noteText = source.slice(triggerIndex + trigger.length).trim();
  noteText = noteText.replace(/^[\s:,\-–—]+/, "").trim();
  noteText = noteText.replace(/^["“”'`]+|["“”'`]+$/g, "").trim();

  const quoted = [...source.matchAll(/["“]([^"”]+)["”]/g)]
    .map((m) => String(m[1] || "").trim())
    .filter(Boolean);
  if (!noteText && quoted.length) {
    noteText = quoted[quoted.length - 1];
  }

  if (!noteText) {
    noteText = source
      .replace(/\bclementine\b[:,]?\s*/ig, "")
      .replace(
        new RegExp(
          `\\b(?:can you|could you|please|hey)?\\s*${escapeRegex(trigger)}\\b`,
          "i"
        ),
        ""
      )
      .replace(/^[\s:,\-–—]+/, "")
      .trim();
  }

  noteText = noteText.replace(/\b(?:please|for me)\b$/i, "").trim();
  noteText = noteText.replace(/\s+/g, " ");

  if (!noteText || noteText.length < 3) {
    return {
      shouldCapture: true,
      needsContent: true,
      noteText: "",
      trigger,
    };
  }

  return {
    shouldCapture: true,
    needsContent: false,
    noteText,
    trigger,
  };
}

function buildCapturedNoteTitle(noteText) {
  const cleaned = String(noteText || "")
    .replace(/\s+/g, " ")
    .replace(/^[\s"'`]+|[\s"'`]+$/g, "")
    .trim();
  if (!cleaned) return "Clementine Note";
  const sentence = cleaned.split(/[.!?]/)[0] || cleaned;
  return trimToMax(sentence, 72);
}

function formatNoteTimestamp(date = new Date()) {
  return date.toISOString().replace("T", " ").replace("Z", " UTC");
}

function runOsaScript(script, args = []) {
  return new Promise((resolve, reject) => {
    execFile(
      "osascript",
      ["-e", script, ...args],
      { timeout: 10_000 },
      (error, stdout, stderr) => {
        if (error) {
          const err = new Error(String(stderr || error.message || "osascript failed"));
          err.cause = error;
          return reject(err);
        }
        resolve(String(stdout || "").trim());
      }
    );
  });
}

async function saveCapturedNoteToAppleNotes({ title, body, folderName }) {
  const script = `
on run argv
  set noteTitle to item 1 of argv
  set noteBody to item 2 of argv
  set folderName to item 3 of argv
  tell application "Notes"
    if not (exists account 1) then error "No Notes account configured."
    set targetAccount to account 1
    set targetFolder to missing value
    if folderName is not "" then
      repeat with f in folders of targetAccount
        if name of f is folderName then
          set targetFolder to f
          exit repeat
        end if
      end repeat
    end if
    if targetFolder is missing value then
      set targetFolder to folder 1 of targetAccount
    end if
    set createdNote to make new note at targetFolder with properties {name:noteTitle, body:noteBody}
    return name of createdNote
  end tell
end run
`.trim();

  const created = await runOsaScript(script, [title, body, folderName || ""]);
  return { createdName: created || title };
}

function saveCapturedNoteToFile({ title, body }) {
  fs.mkdirSync(NOTE_CAPTURE_FALLBACK_DIR, { recursive: true });
  const stamp = new Date().toISOString().replace(/[:.]/g, "-");
  const fileName = `${stamp}-${slugifyForFilename(title)}.md`;
  const filePath = path.join(NOTE_CAPTURE_FALLBACK_DIR, fileName);
  const content = `# ${title}\n\n${body}\n`;
  fs.writeFileSync(filePath, content, "utf8");
  return { filePath };
}

async function captureLocalNote({ noteText, reqId }) {
  const title = buildCapturedNoteTitle(noteText);
  const body = `${noteText}\n\n---\nSaved by CLEMENTINE at ${formatNoteTimestamp()}`;
  const preferredTarget = NOTE_CAPTURE_TARGET;

  if (!ENABLE_LOCAL_NOTE_CAPTURE) {
    return {
      status: "disabled",
      target: "none",
      title,
      error: "Local note capture disabled.",
    };
  }

  const canUseAppleNotes = process.platform === "darwin";
  if (preferredTarget === "apple_notes" && canUseAppleNotes) {
    try {
      await saveCapturedNoteToAppleNotes({
        title,
        body,
        folderName: NOTE_CAPTURE_FOLDER,
      });
      return {
        status: "saved",
        target: "apple_notes",
        title,
      };
    } catch (error) {
      console.log(
        `[${reqId}] note_capture apple_notes_failed=${String(error?.message || error)}`
      );
    }
  }

  try {
    const fileSave = saveCapturedNoteToFile({ title, body });
    return {
      status: "saved",
      target: "file",
      title,
      path: fileSave.filePath,
    };
  } catch (error) {
    return {
      status: "failed",
      target: preferredTarget,
      title,
      error: String(error?.message || error),
    };
  }
}

function buildNoteCaptureReply(result) {
  const state = result && typeof result === "object" ? result : {};
  const title = trimToMax(state.title || "your note", 72);

  if (state.status === "needs_confirmation") {
    return buildPendingLocalActionConfirmationReply({
      summary: state.summary || "",
    });
  }

  if (state.status === "needs_content") {
    return [
      "I can do that.",
      "",
      "Say \"write this down:\" and the exact note, and I'll save it.",
    ].join("\n");
  }

  if (state.status === "saved" && state.target === "apple_notes") {
    return [
      "Got it.",
      "",
      `I saved that to Notes as "${title}".`,
    ].join("\n");
  }

  if (state.status === "saved" && state.target === "file") {
    return [
      "Got it.",
      "",
      `I saved that on this device as "${title}".`,
    ].join("\n");
  }

  return [
    "I tried to save that, but it didn't go through.",
    "",
    "Say it one more time and I'll retry.",
  ].join("\n");
}

function buildEmailComposeUrl({ to, subject, body, target }) {
  const safeTo = normalizeEmailAddress(to);
  if (!safeTo) return { url: "", target: "none", transport: "none" };

  const safeSubject = trimToMax(String(subject || "").trim(), 120);
  const safeBody = trimToMax(String(body || "").trim(), EMAIL_COMPOSE_BODY_MAX_CHARS);
  const normalizedTarget = parseOneOf(
    String(target || EMAIL_SEND_TARGET || "mailto").toLowerCase(),
    EMAIL_COMPOSE_TARGETS,
    "mailto"
  );

  if (normalizedTarget === "gmail") {
    const gmail = new URL("https://mail.google.com/mail/");
    gmail.searchParams.set("view", "cm");
    gmail.searchParams.set("fs", "1");
    gmail.searchParams.set("to", safeTo);
    if (safeSubject) gmail.searchParams.set("su", safeSubject);
    if (safeBody) gmail.searchParams.set("body", safeBody);
    return { url: gmail.toString(), target: "gmail", transport: "browser" };
  }

  if (normalizedTarget === "outlook") {
    const outlook = new URL("https://outlook.live.com/mail/0/deeplink/compose");
    outlook.searchParams.set("to", safeTo);
    if (safeSubject) outlook.searchParams.set("subject", safeSubject);
    if (safeBody) outlook.searchParams.set("body", safeBody);
    return { url: outlook.toString(), target: "outlook", transport: "browser" };
  }

  if (normalizedTarget === "yahoo") {
    const yahoo = new URL("https://compose.mail.yahoo.com/");
    yahoo.searchParams.set("to", safeTo);
    if (safeSubject) yahoo.searchParams.set("subject", safeSubject);
    if (safeBody) yahoo.searchParams.set("body", safeBody);
    return { url: yahoo.toString(), target: "yahoo", transport: "browser" };
  }

  const params = new URLSearchParams();
  if (safeSubject) params.set("subject", safeSubject);
  if (safeBody) params.set("body", safeBody);
  const query = params.toString();
  const mailtoUrl = `mailto:${encodeURIComponent(safeTo)}${query ? `?${query}` : ""}`;
  return { url: mailtoUrl, target: "mailto", transport: "mail_app" };
}

async function sendLocalEmail({ recipient, subject, body, reqId }) {
  const to = normalizeEmailAddress(recipient);
  const cleanBody = String(body || "").replace(/\s+/g, " ").trim();
  const cleanSubject = trimToMax(String(subject || "").trim(), 120);

  if (!ENABLE_LOCAL_EMAIL_SEND) {
    return {
      status: "disabled",
      action: "none",
      target: "none",
      transport: "none",
      to,
      subject: cleanSubject,
      composeUrl: "",
      error: "Local email compose disabled.",
    };
  }

  if (!to) {
    return {
      status: "needs_recipient",
      action: "none",
      target: EMAIL_SEND_TARGET,
      transport: "none",
      to: "",
      subject: cleanSubject,
      composeUrl: "",
    };
  }

  if (!cleanBody || cleanBody.length < 3) {
    return {
      status: "needs_content",
      action: "none",
      target: EMAIL_SEND_TARGET,
      transport: "none",
      to,
      subject: cleanSubject || "Message from CLEMENTINE",
      composeUrl: "",
    };
  }

  const finalSubject = cleanSubject || buildCapturedEmailSubject(cleanBody);
  const finalBody = `${cleanBody}\n\n---\nDrafted by CLEMENTINE at ${formatNoteTimestamp()}`;
  try {
    const compose = buildEmailComposeUrl({
      to,
      subject: finalSubject,
      body: finalBody,
      target: EMAIL_SEND_TARGET,
    });
    if (!compose.url) {
      return {
        status: "failed",
        action: "none",
        target: EMAIL_SEND_TARGET,
        transport: "none",
        to,
        subject: finalSubject,
        composeUrl: "",
        error: "Could not build compose URL.",
      };
    }
    return {
      status: "composed",
      action: "compose",
      target: compose.target,
      transport: compose.transport,
      to,
      subject: finalSubject,
      composeUrl: compose.url,
    };
  } catch (error) {
    console.log(
      `[${reqId}] email_compose_failed=${String(error?.message || error)}`
    );
    return {
      status: "failed",
      action: "none",
      target: EMAIL_SEND_TARGET,
      transport: "none",
      to,
      subject: finalSubject,
      composeUrl: "",
      error: String(error?.message || error),
    };
  }
}

function buildEmailSendReply(result) {
  const state = result && typeof result === "object" ? result : {};
  const to = trimToMax(state.to || "recipient", 120);
  const subject = trimToMax(state.subject || "your message", 120);

  if (state.status === "needs_confirmation") {
    return buildPendingLocalActionConfirmationReply({
      summary: state.summary || "",
    });
  }

  if (state.status === "canceled") {
    return [
      "Okay, canceled.",
      "",
      "I cleared the pending email.",
    ].join("\n");
  }

  if (state.status === "needs_recipient") {
    return [
      "I can draft that.",
      "",
      "Tell me the recipient email and the message.",
    ].join("\n");
  }

  if (state.status === "needs_content") {
    return [
      "I have the recipient.",
      "",
      `Now say the message body and I will open a draft to ${to}${subject ? ` with subject "${subject}"` : ""}.`,
    ].join("\n");
  }

  if (state.status === "composed") {
    return [
      "Done.",
      "",
      `I opened a draft to ${to}${subject ? ` with subject "${subject}"` : ""}. Review and hit Send in your email app.`,
    ].join("\n");
  }

  if (state.status === "duplicate") {
    return [
      "That draft is already queued.",
      "",
      "I skipped opening another duplicate compose window.",
    ].join("\n");
  }

  if (state.status === "disabled") {
    return [
      "Email compose is disabled right now.",
      "",
      "Enable local email compose and try again.",
    ].join("\n");
  }

  return [
    "I could not prepare that draft right now.",
    "",
    "Say \"send email to\" plus recipient, subject, and message so I can retry cleanly.",
  ].join("\n");
}

async function draftSecretaryEmailFromPrompt({
  prompt,
  context,
  tone,
  recipient,
  rid = "secretary_email",
}) {
  const cleanPrompt = normalizeSnippet(prompt, 1600);
  const cleanContext = normalizeSnippet(context, 2200);
  const cleanTone = normalizeSnippet(tone, 120);
  if (!cleanPrompt) {
    return {
      subject: "",
      body: "",
      mode: "empty_prompt",
    };
  }

  if (!OPENAI_API_KEY) {
    const fallbackBody = cleanContext
      ? `${cleanPrompt}\n\nContext:\n${cleanContext}`
      : cleanPrompt;
    return {
      subject: buildCapturedEmailSubject(cleanPrompt),
      body: fallbackBody,
      mode: "fallback_no_llm",
    };
  }

  const system = [
    "You draft concise professional emails for a personal secretary assistant.",
    "Return strict JSON only with keys: subject, body.",
    "Rules:",
    "- subject <= 90 characters.",
    "- body 70-220 words unless user asks very short.",
    "- clear structure: opening, core message, concrete next step.",
    "- no markdown, no bullet list unless requested.",
    "- preserve sender intent and tone.",
  ].join("\n");

  const user = [
    `recipient: ${normalizeEmailAddress(recipient) || "unspecified"}`,
    `tone: ${cleanTone || "clear, warm, direct"}`,
    `prompt: ${cleanPrompt}`,
    cleanContext ? `context: ${cleanContext}` : "",
  ].filter(Boolean).join("\n\n");

  try {
    const resp = await fetchWithTimeout(
      "https://api.openai.com/v1/chat/completions",
      {
        method: "POST",
        headers: {
          Authorization: `Bearer ${OPENAI_API_KEY}`,
          "Content-Type": "application/json",
          "OpenAI-Beta": "realtime=v1",
        },
        body: JSON.stringify({
          model: SECRETARY_EMAIL_DRAFT_MODEL || CHAT_MODEL_FAST,
          temperature: 0.35,
          max_tokens: 500,
          messages: [
            { role: "system", content: system },
            { role: "user", content: user },
          ],
        }),
      },
      SECRETARY_EMAIL_DRAFT_TIMEOUT_MS
    );
    if (!resp.ok) {
      const bodyText = await resp.text();
      console.log(`[${rid}] secretary_email_draft_failed status=${resp.status} body=${trimToMax(bodyText, 220)}`);
      return {
        subject: buildCapturedEmailSubject(cleanPrompt),
        body: cleanPrompt,
        mode: "fallback_http_error",
      };
    }
    const json = await resp.json();
    const raw = String(json?.choices?.[0]?.message?.content || "").trim();
    const parsed = extractJsonObject(raw);
    const subject = trimToMax(
      parsed && typeof parsed === "object"
        ? String(parsed.subject || "")
        : "",
      90
    );
    const body = normalizeSnippet(
      parsed && typeof parsed === "object"
        ? String(parsed.body || "")
        : "",
      4000
    );
    if (!subject || !body) {
      return {
        subject: buildCapturedEmailSubject(cleanPrompt),
        body: cleanPrompt,
        mode: "fallback_parse",
      };
    }
    return {
      subject,
      body,
      mode: "llm_draft",
    };
  } catch (err) {
    console.log(`[${rid}] secretary_email_draft_error=${String(err?.message || err)}`);
    return {
      subject: buildCapturedEmailSubject(cleanPrompt),
      body: cleanPrompt,
      mode: "fallback_exception",
    };
  }
}

function buildLinkedInProfileTextFromPayload(payload) {
  const body = payload && typeof payload === "object" ? payload : {};
  const parts = [];
  const primary = normalizeSnippet(
    body.profile_text ?? body.profileText ?? body.text ?? body.raw_profile ?? "",
    LINKEDIN_ANALYSIS_MAX_CHARS
  );
  if (primary) parts.push(primary);

  const headline = normalizeSnippet(body.headline, 220);
  if (headline) parts.push(`Headline: ${headline}`);

  const about = normalizeSnippet(body.about, 2400);
  if (about) parts.push(`About: ${about}`);

  const skills = Array.isArray(body.skills)
    ? body.skills.map((item) => normalizeSnippet(item, 60)).filter(Boolean)
    : String(body.skills || "").split(/[,\n|]/g).map((item) => normalizeSnippet(item, 60)).filter(Boolean);
  if (skills.length) {
    parts.push(`Skills: ${skills.slice(0, 80).join(", ")}`);
  }

  const experiences = Array.isArray(body.experiences)
    ? body.experiences.map((item) => {
      if (typeof item === "string") return normalizeSnippet(item, 360);
      if (!item || typeof item !== "object") return "";
      const title = normalizeSnippet(item.title, 120);
      const company = normalizeSnippet(item.company, 120);
      const summary = normalizeSnippet(item.summary ?? item.description, 360);
      return [title, company, summary].filter(Boolean).join(" - ");
    }).filter(Boolean)
    : [];
  if (experiences.length) {
    parts.push(`Experience:\n- ${experiences.slice(0, 40).join("\n- ")}`);
  }

  const education = Array.isArray(body.education)
    ? body.education.map((item) => normalizeSnippet(item, 180)).filter(Boolean)
    : String(body.education || "").split(/[,\n|]/g).map((item) => normalizeSnippet(item, 180)).filter(Boolean);
  if (education.length) {
    parts.push(`Education: ${education.slice(0, 30).join(" | ")}`);
  }

  return normalizeSnippet(parts.join("\n\n"), LINKEDIN_ANALYSIS_MAX_CHARS);
}

function heuristicLinkedInAnalysis({
  profileText,
  targetRole,
}) {
  const text = String(profileText || "");
  const lower = text.toLowerCase();
  const lines = text.split(/\n+/).map((x) => x.trim()).filter(Boolean);
  const hasHeadline = lines.length > 0 && lines[0].length >= 12;
  const hasAbout = lower.includes("about:");
  const metricMatches = text.match(/\b\d+(\.\d+)?\s*(%|x|k|m|\+)?\b/g) || [];
  const hasMetrics = metricMatches.length >= 2;
  const hasActionVerbs = textContainsAny(lower, [
    "led", "built", "shipped", "grew", "scaled", "launched", "improved", "managed", "designed",
  ]);
  const hasKeywords = textContainsAny(lower, [
    "product", "engineering", "marketing", "sales", "operations", "design", "founder", "strategy",
  ]);
  const hasContactCue = textContainsAny(lower, ["open to", "reach out", "contact", "email", "dm"]);

  const strengths = [];
  const weaknesses = [];
  const actionPlan = [];

  if (hasHeadline) strengths.push("Headline presence is clear enough to anchor first impression.");
  else weaknesses.push("Headline is weak or missing; profile may feel generic in search results.");

  if (hasMetrics) strengths.push("You use quantified evidence, which increases credibility quickly.");
  else weaknesses.push("Few measurable outcomes; impact is hard for recruiters to verify.");

  if (hasActionVerbs) strengths.push("Experience language uses strong action verbs.");
  else weaknesses.push("Experience bullets are passive; they need stronger action framing.");

  if (hasKeywords) strengths.push("Role-relevant keywords are present for discoverability.");
  else weaknesses.push("Keyword coverage is low; profile may underperform in recruiter search.");

  if (hasAbout) strengths.push("About section exists and supports personal narrative.");
  else weaknesses.push("About section is missing or thin; story and positioning are unclear.");

  if (!hasContactCue) {
    weaknesses.push("No clear call-to-action for outreach or next step.");
  }

  actionPlan.push("Rewrite headline to role + specialty + measurable value.");
  actionPlan.push("Add 3-5 quantified outcomes across recent roles (%, revenue, time saved, scope).");
  actionPlan.push("Tighten About to 4-6 lines: identity, proof, domain focus, and CTA.");
  if (targetRole) {
    actionPlan.push(`Mirror top keywords for target role: ${targetRole}.`);
  }

  const scoreBase = 58 +
    (hasHeadline ? 8 : -6) +
    (hasMetrics ? 12 : -8) +
    (hasActionVerbs ? 8 : -6) +
    (hasKeywords ? 8 : -6) +
    (hasAbout ? 6 : -4);
  const profileScore = Math.max(25, Math.min(95, scoreBase));

  const rewrittenHeadline = targetRole
    ? `${targetRole} | Builds measurable outcomes through clear strategy and execution`
    : "Outcome-focused professional | Turns strategy into measurable results";
  const rewrittenAbout = [
    "I build practical systems that create measurable outcomes.",
    "My work focuses on clear execution, cross-functional collaboration, and continuous improvement.",
    "I care about impact you can quantify, not just activity.",
    "Open to conversations about roles where ownership and results matter.",
  ].join(" ");

  return {
    summary: "Profile has a solid foundation, but it needs sharper positioning and more measurable proof.",
    profileScore,
    strengths: strengths.slice(0, 6),
    weaknesses: weaknesses.slice(0, 6),
    actionPlan: actionPlan.slice(0, 6),
    rewrittenHeadline,
    rewrittenAbout,
    mode: "heuristic_fallback",
  };
}

async function analyzeLinkedInProfilePayload({
  profileText,
  targetRole,
  goals,
  rid = "linkedin",
}) {
  const cleanProfile = normalizeSnippet(profileText, LINKEDIN_ANALYSIS_MAX_CHARS);
  const cleanRole = normalizeSnippet(targetRole, 160);
  const cleanGoals = normalizeSnippet(goals, 320);
  if (!cleanProfile) {
    return {
      error: "empty_profile",
      message: "Provide profile_text or structured fields like headline/about/experiences.",
    };
  }

  const fallback = heuristicLinkedInAnalysis({
    profileText: cleanProfile,
    targetRole: cleanRole,
  });

  if (!LINKEDIN_ANALYSIS_ENABLED || !OPENAI_API_KEY) {
    return fallback;
  }

  const system = [
    "You are a senior LinkedIn profile strategist.",
    "Analyze profile text for recruiter-readability, positioning clarity, credibility, and impact proof.",
    "Return strict JSON only with keys:",
    "summary, profileScore, strengths, weaknesses, actionPlan, rewrittenHeadline, rewrittenAbout, mode",
    "Rules:",
    "- strengths/weaknesses/actionPlan must each have 3-6 concise strings.",
    "- weaknesses must be specific and evidence-based from the provided profile text.",
    "- actionPlan must be practical and ordered by priority.",
    "- rewrittenHeadline <= 180 chars.",
    "- rewrittenAbout <= 1200 chars.",
    "- no markdown, no extra keys.",
  ].join("\n");

  const userPrompt = [
    `target_role: ${cleanRole || "not specified"}`,
    `goals: ${cleanGoals || "improve clarity and conversion"}`,
    "profile_text:",
    cleanProfile,
  ].join("\n\n");

  try {
    const resp = await fetchWithTimeout(
      "https://api.openai.com/v1/chat/completions",
      {
        method: "POST",
        headers: {
          Authorization: `Bearer ${OPENAI_API_KEY}`,
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          model: LINKEDIN_ANALYSIS_MODEL || CHAT_MODEL_FAST,
          temperature: 0.2,
          max_tokens: 900,
          messages: [
            { role: "system", content: system },
            { role: "user", content: userPrompt },
          ],
        }),
      },
      LINKEDIN_ANALYSIS_TIMEOUT_MS
    );
    if (!resp.ok) {
      const text = await resp.text();
      console.log(`[${rid}] linkedin_analyze_failed status=${resp.status} body=${trimToMax(text, 220)}`);
      return fallback;
    }
    const json = await resp.json();
    const raw = String(json?.choices?.[0]?.message?.content || "").trim();
    const parsed = extractJsonObject(raw);
    if (!parsed || typeof parsed !== "object") return fallback;

    const strengths = Array.isArray(parsed.strengths)
      ? parsed.strengths.map((x) => normalizeSnippet(x, 180)).filter(Boolean).slice(0, 6)
      : [];
    const weaknesses = Array.isArray(parsed.weaknesses)
      ? parsed.weaknesses.map((x) => normalizeSnippet(x, 180)).filter(Boolean).slice(0, 6)
      : [];
    const actionPlan = Array.isArray(parsed.actionPlan)
      ? parsed.actionPlan.map((x) => normalizeSnippet(x, 180)).filter(Boolean).slice(0, 6)
      : [];
    if (!strengths.length || !weaknesses.length || !actionPlan.length) {
      return fallback;
    }

    return {
      summary: normalizeSnippet(parsed.summary, 320) || fallback.summary,
      profileScore: Math.max(0, Math.min(100, Number(parsed.profileScore || fallback.profileScore))),
      strengths,
      weaknesses,
      actionPlan,
      rewrittenHeadline: normalizeSnippet(parsed.rewrittenHeadline, 180) || fallback.rewrittenHeadline,
      rewrittenAbout: normalizeSnippet(parsed.rewrittenAbout, 1200) || fallback.rewrittenAbout,
      mode: "llm_analysis",
    };
  } catch (err) {
    console.log(`[${rid}] linkedin_analyze_error=${String(err?.message || err)}`);
    return fallback;
  }
}

function normalizeAssistantSelfName(value) {
  const cleaned = String(value || "")
    .replace(/^[`"'“”‘’\s]+|[`"'“”‘’\s]+$/g, "")
    .replace(/\s+/g, " ")
    .replace(/[^A-Za-z0-9' -]/g, "")
    .trim();
  if (!cleaned) return "";
  if (cleaned.length < 2) return "";
  const bounded = cleaned.slice(0, ASSISTANT_SELF_NAME_MAX_CHARS).trim();
  if (!bounded) return "";
  const lower = bounded.toLowerCase();
  if (["you", "yourself", "me", "myself", "assistant", "ai", "bot"].includes(lower)) {
    return "";
  }
  const hasUpper = /[A-Z]/.test(bounded);
  if (hasUpper) return bounded;
  return bounded
    .split(" ")
    .filter(Boolean)
    .map((part) => `${part.charAt(0).toUpperCase()}${part.slice(1)}`)
    .join(" ");
}

function normalizeUserPersonName(value, maxChars = USER_PRIMARY_NAME_MAX_CHARS) {
  const cleaned = String(value || "")
    .replace(/^[`"'“”‘’\s]+|[`"'“”‘’\s]+$/g, "")
    .replace(/\s+/g, " ")
    .replace(/[^A-Za-z0-9' -]/g, "")
    .trim();
  if (!cleaned) return "";
  if (cleaned.length < 2) return "";
  const bounded = cleaned.slice(0, maxChars).trim();
  if (!bounded) return "";
  const lower = bounded.toLowerCase();
  if (
    [
      "me", "myself", "you", "yourself", "name", "remember", "something", "someone",
      "later", "tomorrow", "today", "tonight", "friend", "person", "unknown",
      "this", "that", "it", "him", "her",
    ].includes(lower)
  ) {
    return "";
  }
  return bounded
    .split(" ")
    .filter(Boolean)
    .slice(0, 3)
    .map((part) => `${part.charAt(0).toUpperCase()}${part.slice(1)}`)
    .join(" ");
}

function normalizeRememberedRelation(value) {
  const cleaned = String(value || "")
    .replace(/\s+/g, " ")
    .replace(/[^A-Za-z0-9' -]/g, "")
    .trim()
    .toLowerCase();
  if (!cleaned) return "";
  return cleaned.slice(0, 48);
}

function sanitizeRememberedPeople(items, maxItems = USER_MEMORY_REMEMBERED_PEOPLE_MAX) {
  const source = Array.isArray(items) ? items : [];
  const deduped = new Map();
  for (const item of source) {
    const raw = item && typeof item === "object" ? item : { name: item };
    const name = normalizeUserPersonName(raw.name);
    if (!name) continue;
    const relation = normalizeRememberedRelation(raw.relation || raw.role || raw.label);
    const note = normalizeSnippet(raw.note, 90);
    const updatedAt = Math.max(0, Number(raw.updatedAt || raw.ts || Date.now()));
    const key = name.toLowerCase();
    const prev = deduped.get(key);
    if (!prev || updatedAt >= Number(prev.updatedAt || 0)) {
      deduped.set(key, { name, relation, note, updatedAt });
    }
  }
  return [...deduped.values()]
    .sort((a, b) => Number(a.updatedAt || 0) - Number(b.updatedAt || 0))
    .slice(-Math.max(1, maxItems));
}

function upsertRememberedPerson(items, person, maxItems = USER_MEMORY_REMEMBERED_PEOPLE_MAX) {
  const next = sanitizeRememberedPeople(items, maxItems);
  const name = normalizeUserPersonName(person?.name);
  if (!name) return next;
  const relation = normalizeRememberedRelation(person?.relation);
  const note = normalizeSnippet(person?.note, 90);
  const updatedAt = Math.max(0, Number(person?.updatedAt || Date.now()));
  const idx = next.findIndex((entry) => String(entry?.name || "").toLowerCase() === name.toLowerCase());
  if (idx >= 0) {
    const prev = next[idx];
    next[idx] = {
      name,
      relation: relation || String(prev?.relation || ""),
      note: note || String(prev?.note || ""),
      updatedAt: Math.max(updatedAt, Number(prev?.updatedAt || 0)),
    };
  } else {
    next.push({ name, relation, note, updatedAt });
  }
  return sanitizeRememberedPeople(next, maxItems);
}

function extractUserIdentityIntent(transcript) {
  const source = String(transcript || "").trim();
  const out = {
    clearPrimaryName: false,
    primaryName: "",
    rememberedPeople: [],
    hasUpdate: false,
  };
  if (!source) return out;

  if (/\b(?:forget|clear|reset)\s+(?:my|the)\s+name\b/i.test(source)) {
    out.clearPrimaryName = true;
    out.hasUpdate = true;
  }

  const primaryPatterns = [
    /\bmy\s+name(?:\s+is|['’]s)\s+([A-Za-z][A-Za-z0-9' -]{1,40})\b/i,
    /\b(?:call\s+me|you\s+can\s+call\s+me|i\s+go\s+by)\s+([A-Za-z][A-Za-z0-9' -]{1,40})\b/i,
    /\bremember\s+my\s+name(?:\s+is)?\s+([A-Za-z][A-Za-z0-9' -]{1,40})\b/i,
  ];
  for (const re of primaryPatterns) {
    const match = source.match(re);
    if (!match) continue;
    const candidate = normalizeUserPersonName(match[1]);
    if (!candidate) continue;
    out.primaryName = candidate;
    out.hasUpdate = true;
    break;
  }

  const rememberGate = /\b(?:remember|don['’]?t\s+forget)\b/i.test(source);
  if (rememberGate) {
    const remembered = [];
    const addRemembered = (nameRaw, relationRaw = "", noteRaw = "") => {
      const name = normalizeUserPersonName(nameRaw);
      if (!name) return;
      remembered.push({
        name,
        relation: normalizeRememberedRelation(relationRaw),
        note: normalizeSnippet(noteRaw, 90),
        updatedAt: Date.now(),
      });
    };

    let match;
    const namedRelationRe = /(?:remember|don['’]?t\s+forget)\s+(?:that\s+)?([A-Za-z][A-Za-z0-9' -]{1,40})\s+is\s+my\s+([A-Za-z][A-Za-z0-9' -]{1,40})/gi;
    while ((match = namedRelationRe.exec(source)) !== null) {
      addRemembered(match[1], match[2]);
    }

    const relationPairRe = /([A-Za-z][A-Za-z0-9' -]{1,40})\s+is\s+my\s+([A-Za-z][A-Za-z0-9' -]{1,40})/gi;
    while ((match = relationPairRe.exec(source)) !== null) {
      addRemembered(match[1], match[2]);
    }

    const simpleRememberRe = /(?:remember|don['’]?t\s+forget)\s+(?:about\s+)?([A-Za-z][A-Za-z0-9' -]{1,40})\b/gi;
    while ((match = simpleRememberRe.exec(source)) !== null) {
      addRemembered(match[1], "");
    }

    out.rememberedPeople = sanitizeRememberedPeople(remembered, USER_MEMORY_REMEMBERED_PEOPLE_MAX);
    if (out.rememberedPeople.length > 0) {
      out.hasUpdate = true;
    }
  }

  return out;
}

function applyUserIdentityIntentToMemory(memory, intent, nowTs = Date.now()) {
  const base = memory && typeof memory === "object" ? memory : createEmptyEmotionMemory();
  const update = intent && typeof intent === "object" ? intent : {};

  if (Boolean(update.clearPrimaryName)) {
    base.userPrimaryName = "";
    base.userPrimaryNameUpdatedAt = nowTs;
  }

  const primaryName = normalizeUserPersonName(update.primaryName);
  if (primaryName) {
    base.userPrimaryName = primaryName;
    base.userPrimaryNameUpdatedAt = nowTs;
  }

  const remembered = Array.isArray(update.rememberedPeople) ? update.rememberedPeople : [];
  if (remembered.length) {
    let people = sanitizeRememberedPeople(base.rememberedPeople, USER_MEMORY_REMEMBERED_PEOPLE_MAX);
    for (const person of remembered) {
      people = upsertRememberedPerson(people, { ...person, updatedAt: nowTs }, USER_MEMORY_REMEMBERED_PEOPLE_MAX);
    }
    base.rememberedPeople = people;
  } else {
    base.rememberedPeople = sanitizeRememberedPeople(base.rememberedPeople, USER_MEMORY_REMEMBERED_PEOPLE_MAX);
  }

  base.lastUpdatedAt = nowTs;
  return base;
}

function extractAssistantRenameIntent(transcript) {
  const source = String(transcript || "").trim();
  if (!source) return { name: "", source: "none" };

  if (/\b(?:reset|clear)\s+(?:your\s+)?name\b/i.test(source)) {
    return { name: DEFAULT_ASSISTANT_SELF_NAME, source: "voice_reset" };
  }

  const patterns = [
    { source: "voice_call_you", re: /\bcall\s+you\s+([A-Za-z][A-Za-z0-9' -]{1,40})\b/i },
    { source: "voice_name_you", re: /\bname\s+you\s+([A-Za-z][A-Za-z0-9' -]{1,40})\b/i },
    {
      source: "voice_refer_as",
      re: /\b(?:refer\s+to\s+you\s+as|have\s+to\s+call\s+you|let\s+me\s+call\s+you)\s+([A-Za-z][A-Za-z0-9' -]{1,40})\b/i,
    },
    {
      source: "voice_change_name",
      re: /\b(?:change|set)\s+your\s+name\s+to\s+([A-Za-z][A-Za-z0-9' -]{1,40})\b/i,
    },
    {
      source: "voice_your_name_is",
      re: /\byour\s+name(?:\s+is|['’]s)\s+([A-Za-z][A-Za-z0-9' -]{1,40})\b/i,
    },
  ];

  const invalid = new Set(["later", "back", "tomorrow", "soon", "again", "now", "it", "that", "this"]);
  for (const pattern of patterns) {
    const match = source.match(pattern.re);
    if (!match) continue;
    const candidateRaw = String(match[1] || "")
      .replace(/\b(?:from\s+now\s+on|for\s+now|please|okay|ok)\b.*$/i, "")
      .trim();
    const candidate = normalizeAssistantSelfName(candidateRaw);
    if (!candidate) continue;
    if (invalid.has(candidate.toLowerCase())) continue;
    return { name: candidate, source: pattern.source };
  }

  return { name: "", source: "none" };
}

function cleanupAssistantIdentityStore(now = Date.now()) {
  const staleMs = Math.max(1, ASSISTANT_IDENTITY_STALE_DAYS) * 24 * 60 * 60 * 1000;
  for (const [ip, identity] of assistantIdentityByIp) {
    const updatedAt = Number(identity?.updatedAt || 0);
    if (!Number.isFinite(updatedAt) || updatedAt <= 0 || (now - updatedAt) > staleMs) {
      assistantIdentityByIp.delete(ip);
    }
  }
  if (assistantIdentityByIp.size <= ASSISTANT_IDENTITY_MAX_TRACKED) return;
  const entries = [...assistantIdentityByIp.entries()]
    .map(([ip, identity]) => ({
      ip,
      updatedAt: Number(identity?.updatedAt || 0),
    }))
    .sort((a, b) => a.updatedAt - b.updatedAt);
  const excess = assistantIdentityByIp.size - ASSISTANT_IDENTITY_MAX_TRACKED;
  for (let i = 0; i < excess; i += 1) {
    assistantIdentityByIp.delete(entries[i].ip);
  }
}

function saveAssistantIdentityStore(now = Date.now()) {
  cleanupAssistantIdentityStore(now);
  const payload = {
    version: 1,
    updatedAt: now,
    entries: [...assistantIdentityByIp.entries()].map(([ip, identity]) => ({
      ip,
      name: String(identity?.name || DEFAULT_ASSISTANT_SELF_NAME),
      updatedAt: Number(identity?.updatedAt || now),
    })),
  };
  writeJsonFileAtomic(ASSISTANT_IDENTITY_STORE_PATH, payload, "assistant_identity");
}

function loadAssistantIdentityStore() {
  const map = new Map();
  try {
    if (!fs.existsSync(ASSISTANT_IDENTITY_STORE_PATH)) {
      return map;
    }
    const raw = fs.readFileSync(ASSISTANT_IDENTITY_STORE_PATH, "utf8");
    const parsed = JSON.parse(raw);
    const entries = Array.isArray(parsed?.entries) ? parsed.entries : [];
    const now = Date.now();
    for (const entry of entries) {
      const ip = normalizeClientIp(entry?.ip);
      const name = normalizeAssistantSelfName(entry?.name);
      const updatedAt = Math.max(0, Math.min(Number(entry?.updatedAt || 0), now));
      if (!ip || ip === "unknown" || !name || !Number.isFinite(updatedAt) || updatedAt <= 0) continue;
      const existing = map.get(ip);
      if (!existing || updatedAt >= Number(existing.updatedAt || 0)) {
        map.set(ip, { name, updatedAt });
      }
    }
  } catch (err) {
    console.error(`[assistant_identity] Failed to load store ${ASSISTANT_IDENTITY_STORE_PATH}:`, err);
  }
  return map;
}

function getAssistantSelfNameForIp(ip) {
  cleanupAssistantIdentityStore(Date.now());
  const key = normalizeClientIp(ip);
  const stored = assistantIdentityByIp.get(key);
  const candidate = normalizeAssistantSelfName(stored?.name);
  return candidate || DEFAULT_ASSISTANT_SELF_NAME;
}

function setAssistantSelfNameForIp(ip, name, now = Date.now()) {
  const key = normalizeClientIp(ip);
  const normalized = normalizeAssistantSelfName(name) || DEFAULT_ASSISTANT_SELF_NAME;
  assistantIdentityByIp.set(key, { name: normalized, updatedAt: now });
  saveAssistantIdentityStore(now);
  return normalized;
}

function sanitizeSnippetList(items, maxItems = 8, maxChars = 170) {
  const source = Array.isArray(items) ? items : [];
  let out = [];
  for (const item of source) {
    const clean = normalizeSnippet(item, maxChars);
    if (!clean) continue;
    out = pushBoundedUnique(out, clean, maxItems);
  }
  return out.slice(-Math.max(1, maxItems));
}

function sanitizeAdaptiveBias(value) {
  const raw = Number(value || 0);
  if (!Number.isFinite(raw)) return 0;
  return Math.max(-ADAPTIVE_BIAS_LIMIT, Math.min(ADAPTIVE_BIAS_LIMIT, raw));
}

function sanitizeAdaptiveQualityTags(items, maxItems = 8) {
  const source = Array.isArray(items) ? items : [];
  const out = [];
  for (const item of source) {
    const tag = String(item || "").trim().toLowerCase();
    if (!tag || !ADAPTIVE_QUALITY_TAGS.has(tag)) continue;
    if (!out.includes(tag)) out.push(tag);
  }
  return out.slice(0, Math.max(1, maxItems));
}

function sanitizeAdaptiveHistoryItems(items, maxItems = ADAPTIVE_HISTORY_MAX) {
  const source = Array.isArray(items) ? items : [];
  const out = [];
  for (const item of source) {
    if (!item || typeof item !== "object") continue;
    const ts = Math.max(0, Number(item.ts || 0));
    const score = clampUnit(item.score, 0.66);
    const sourceTag = normalizeSnippet(item.source, 24) || "heuristic";
    const tags = sanitizeAdaptiveQualityTags(item.tags, 8);
    out.push({ ts, score, source: sourceTag, tags });
  }
  return out.slice(-Math.max(1, maxItems));
}

function sanitizeTimestampList(items, maxItems = 512) {
  const source = Array.isArray(items) ? items : [];
  return source
    .map((x) => Number(x || 0))
    .filter((x) => Number.isFinite(x) && x > 0)
    .slice(-Math.max(1, maxItems));
}

function sanitizeDayStampList(items, maxItems = 56) {
  const source = Array.isArray(items) ? items : [];
  const out = [];
  for (const item of source) {
    const stamp = String(item || "").trim();
    if (!/^\d{4}-\d{2}-\d{2}$/.test(stamp)) continue;
    if (!out.includes(stamp)) out.push(stamp);
  }
  return out.slice(-Math.max(1, maxItems));
}

function sanitizeDailyTurnItems(items, maxItems = 56) {
  const source = Array.isArray(items) ? items : [];
  return source
    .filter((item) => item && typeof item === "object")
    .map((item) => ({
      day: String(item.day || "").trim(),
      count: Math.max(0, Number(item.count || 0)),
    }))
    .filter((item) => /^\d{4}-\d{2}-\d{2}$/.test(item.day))
    .slice(-Math.max(1, maxItems));
}

function sanitizeSocialSparkMoments(items, maxItems = SOCIAL_SPARK_MEMORY_MAX) {
  const source = Array.isArray(items) ? items : [];
  const out = [];
  for (const item of source) {
    if (!item || typeof item !== "object") continue;
    const event = normalizeSnippet(item.event, 96);
    const detail = normalizeSnippet(item.detail, 140);
    const affect = normalizeSnippet(item.affect, 40);
    if (!event && !detail) continue;
    out.push({
      event: event || "met someone",
      detail: detail || "",
      affect: affect || "",
      turn: Math.max(0, Number(item.turn || 0)),
      ts: Math.max(0, Number(item.ts || 0)),
    });
  }
  return out.slice(-Math.max(1, maxItems));
}

function personalitySignalKeys() {
  return [
    "creative_identity",
    "relational_values",
    "emotional_processing",
    "growth_mindset",
    "action_orientation",
    "humor_play",
    "self_reflection",
    "social_connection",
  ];
}

