    order: Math.max(0, Number(entry.order ?? orderFallback)),
    status: normalizeSnippet(entry.status, 24) || "open",
    beatIds: normalizeScreenplayStringList(entry.beatIds, 256, 64),
    createdAt: Math.max(0, Number(entry.createdAt || 0)),
