function normalizeKnowledgeTopic(topic) {
  const raw = String(topic || "")
    .trim()
    .toLowerCase()
    .replace(/[^a-z0-9_]+/g, "_")
    .replace(/^_+|_+$/g, "");
  if (!raw) return "general";
  if (raw === "art" || raw === "arthistory" || raw === "art_hist") return "art_history";
  if (raw === "film" || raw === "films" || raw === "cinema") return "movies";
  if (raw === "compatability" || raw === "relationship_fit") return "compatibility";
  if (raw === "friends" || raw === "friend") return "friendship";
  if (raw === "human" || raw === "connection") return "human_connection";
  return raw;
}

function normalizeKnowledgeTags(raw, maxItems = 12) {
  const source = Array.isArray(raw)
    ? raw
    : (typeof raw === "string" ? raw.split(/[|,]/g) : []);
  const out = [];
  for (const item of source) {
    const tag = String(item || "")
      .trim()
      .toLowerCase()
      .replace(/[^a-z0-9_ -]+/g, "")
      .replace(/\s+/g, " ");
    if (!tag) continue;
    if (!out.includes(tag)) out.push(tag);
    if (out.length >= maxItems) break;
  }
  return out;
}

function buildKnowledgeSearchText(card) {
  return [
    card.topic,
    card.title,
    card.body,
    ...(Array.isArray(card.tags) ? card.tags : []),
  ]
    .join(" ")
    .toLowerCase();
}

function normalizeKnowledgeCard(card, idx = 0) {
  if (!card || typeof card !== "object") return null;
  const topic = normalizeKnowledgeTopic(card.topic);
  const title = normalizeSnippet(card.title, 140);
  const body = normalizeSnippet(card.body, KNOWLEDGE_RAG_CARD_BODY_MAX_CHARS);
  if (!title || !body) return null;
  const tags = normalizeKnowledgeTags(card.tags);
  const source = normalizeSnippet(card.source, 32).toLowerCase() || "knowledge";
  const level = normalizeSnippet(card.level, 24).toLowerCase() || "foundation";
  const normalized = {
    id: normalizeSnippet(card.id, 64) || `k_${idx + 1}`,
    topic: topic || "general",
    title,
    body,
    tags,
    level,
    source,
  };
  normalized.searchText = buildKnowledgeSearchText(normalized);
  return normalized;
}

function loadKnowledgeCards() {
  if (knowledgeCardsCache && Array.isArray(knowledgeCardsCache) && knowledgeCardsCache.length) {
    return knowledgeCardsCache;
  }
  let parsed = null;
  try {
    if (fs.existsSync(KNOWLEDGE_CARDS_FILE)) {
      const raw = fs.readFileSync(KNOWLEDGE_CARDS_FILE, "utf8");
      const json = JSON.parse(raw);
      if (Array.isArray(json)) {
        parsed = json;
      } else if (Array.isArray(json?.cards)) {
        parsed = json.cards;
      }
    }
  } catch (_err) {
    parsed = null;
  }
  const source = Array.isArray(parsed) && parsed.length ? parsed : FALLBACK_KNOWLEDGE_CARDS;
  knowledgeCardsCache = source
    .map((item, idx) => normalizeKnowledgeCard(item, idx))
    .filter(Boolean);
  knowledgeCardsLoadedAt = Date.now();
  return knowledgeCardsCache;
}

function tokenizeKnowledgeQuery(text) {
  return String(text || "")
    .toLowerCase()
    .replace(/[^a-z0-9\s]/g, " ")
    .split(/\s+/)
    .map((x) => x.trim())
    .filter((x) => x.length >= 3 && !KNOWLEDGE_STOPWORDS.has(x));
}

function countKeywordHits(text, keywords) {
  const t = String(text || "");
  return keywords.reduce((count, keyword) => (
    keyword && t.includes(keyword) ? count + 1 : count
  ), 0);
}

function deriveKnowledgeTopicWeights(queryText) {
  const text = String(queryText || "").toLowerCase();
  const weights = {};
  for (const [topic, keywords] of Object.entries(KNOWLEDGE_TOPIC_KEYWORDS)) {
    const hits = countKeywordHits(text, keywords);
    if (hits <= 0) continue;
    weights[topic] = Math.min(1, 0.28 + (hits * 0.18));
  }
  if (textContainsAny(text, ["relationship", "dating", "partner", "breakup"])) {
    weights.compatibility = Math.max(weights.compatibility || 0, 0.42);
    weights.human_connection = Math.max(weights.human_connection || 0, 0.38);
  }
  if (textContainsAny(text, ["hurt", "betrayed", "liar", "lied"])) {
    weights.betrayal = Math.max(weights.betrayal || 0, 0.50);
    weights.empathy = Math.max(weights.empathy || 0, 0.32);
  }
  if (textContainsAny(text, ["friend", "friendship", "best friend"])) {
    weights.friendship = Math.max(weights.friendship || 0, 0.48);
  }
  return weights;
}

function deriveKnowledgeQueryProfile(query, { flags, turnPlanner } = {}) {
  const text = String(query || "").trim().toLowerCase();
  const topicWeights = deriveKnowledgeTopicWeights(text);
  const tokens = tokenizeKnowledgeQuery(text);
  const asksCompare = textContainsAny(text, ["compare", "difference", "vs", "versus"]);
  const asksTimeline = textContainsAny(text, ["timeline", "history", "when did", "origin"]);
  const asksFramework = textContainsAny(text, ["framework", "model", "principle", "theory"]);
  const asksHowTo = textContainsAny(text, ["how", "steps", "practical", "what should i do"]);
  const asksDepth = textContainsAny(text, [
    "in depth",
    "deep",
    "expert",
    "highest level",
    "advanced",
    "nuanced",
    "most important",
  ]);
  const isRelational = Object.keys(topicWeights).some((key) => KNOWLEDGE_RELATIONAL_TOPICS.has(key));
  const isFoundational = Object.keys(topicWeights).some((key) => (
    key === "movies" || key === "art_history" || key === "philosophy" || key === "learning"
  ));
  return {
    text,
    tokens,
    topicWeights,
    asksCompare,
    asksTimeline,
    asksFramework,
    asksHowTo,
    asksDepth,
    isRelational,
    isFoundational,
    vulnerable: Boolean(flags?.isVulnerable || flags?.therapeuticDepth),
    plannerIntent: String(turnPlanner?.intent || "knowledge_answer"),
  };
}

function inferMemoryKnowledgeTopic(text) {
  const weights = deriveKnowledgeTopicWeights(String(text || "").toLowerCase());
  const entries = Object.entries(weights).sort((a, b) => b[1] - a[1]);
  if (!entries.length) return "human_connection";
  return entries[0][0] || "human_connection";
}

function buildKnowledgeMemoryCards(memory, maxItems = 6) {
  if (!memory || typeof memory !== "object") return [];
  const out = [];
  const turns = Math.max(0, Number(memory.turns || 0));
  const themes = sanitizeActiveThemes(
    Array.isArray(memory.sessionThreads) && memory.sessionThreads.length
      ? memory.sessionThreads
      : memory.activeThemes,
    turns
  ).slice(0, Math.max(1, Math.min(maxItems, ACTIVE_THEME_MAX)));
  for (const theme of themes) {
    const label = normalizeThemeLabel(theme?.label, "User pattern");
    const summary = normalizeThemeSummary(theme?.summary, "");
    if (!summary) continue;
    const joined = `${label} ${summary} ${normalizeThemeTone(theme?.emotionalTone, "")}`;
    const topic = inferMemoryKnowledgeTopic(joined);
    out.push({
      id: `m_theme_${normalizeSnippet(theme?.key, 42) || randomUUID().slice(0, 8)}`,
      topic,
      title: `${label} (user context)`,
      body: normalizeSnippet(summary, KNOWLEDGE_RAG_CARD_BODY_MAX_CHARS),
      tags: normalizeKnowledgeTags([topic, "memory", "user_context"]),
      level: "contextual",
      source: "memory",
      salience: clampUnit(theme?.salience, 0.45),
      searchText: `${topic} ${label} ${summary}`.toLowerCase(),
    });
  }

  const facts = Array.isArray(memory.listeningFacts)
    ? [...memory.listeningFacts].reverse().slice(0, Math.max(1, maxItems - out.length))
    : [];
  for (const fact of facts) {
    const clean = normalizeSnippet(fact, 180);
    if (!clean) continue;
    const topic = inferMemoryKnowledgeTopic(clean);
    out.push({
      id: `m_fact_${hash01(clean).toString(16).slice(2, 10)}`,
      topic,
      title: "User context cue",
      body: clean,
      tags: normalizeKnowledgeTags([topic, "memory", "listening_fact"]),
      level: "contextual",
      source: "memory",
      salience: 0.40,
      searchText: `${topic} ${clean}`.toLowerCase(),
    });
    if (out.length >= maxItems) break;
  }
  return out.slice(0, maxItems);
}

function scoreKnowledgeCardLexical(card, profile) {
  const queryTokens = Array.isArray(profile?.tokens) ? profile.tokens : [];
  const topicWeights = profile?.topicWeights && typeof profile.topicWeights === "object"
    ? profile.topicWeights
    : {};
  const titleLower = String(card?.title || "").toLowerCase();
  const bodyLower = String(card?.body || "").toLowerCase();
  const topicLower = String(card?.topic || "").toLowerCase();
  const tagsLower = Array.isArray(card?.tags)
    ? card.tags.join(" ").toLowerCase()
    : "";
  const haystack = String(card?.searchText || `${topicLower} ${titleLower} ${bodyLower}`).toLowerCase();

  let score = 0;
  for (const token of queryTokens) {
    if (titleLower.includes(token)) score += 1.95;
    else if (tagsLower.includes(token)) score += 1.35;
    else if (topicLower.includes(token)) score += 1.15;
    else if (bodyLower.includes(token)) score += 0.92;
    else if (haystack.includes(token)) score += 0.62;
  }

  const topicWeight = Number(topicWeights[topicLower] || 0);
  if (topicWeight > 0) score += topicWeight * 1.8;

  if (profile?.asksCompare && textContainsAny(card?.body, ["versus", "tradeoff", "contrast", "difference"])) {
    score += 0.35;
  }
  if (profile?.asksTimeline && textContainsAny(card?.body, ["century", "period", "timeline", "histor", "origin"])) {
    score += 0.28;
  }
  if (profile?.asksFramework && textContainsAny(card?.body, ["framework", "model", "principle", "pattern"])) {
    score += 0.26;
  }
  if (profile?.asksDepth && String(card?.level || "").toLowerCase() !== "foundation") {
    score += 0.22;
  }
  if (profile?.isRelational && KNOWLEDGE_RELATIONAL_TOPICS.has(topicLower)) {
    score += 0.42;
  }
  if (card?.source === "memory") {
    score += 0.24;
  }

  return score;
}

function hashSha256(text) {
  return createHash("sha256")
    .update(String(text || ""), "utf8")
    .digest("hex");
}

function sanitizeEmbeddingVector(vec) {
  if (!Array.isArray(vec) || !vec.length) return null;
  const out = [];
  for (const value of vec) {
    const n = Number(value);
    if (!Number.isFinite(n)) return null;
    out.push(n);
  }
  return out.length ? out : null;
}

function vectorNorm(vec) {
  if (!Array.isArray(vec) || !vec.length) return 0;
  let sum = 0;
  for (const value of vec) sum += value * value;
  return Math.sqrt(sum);
}

function dotProduct(a, b) {
  if (!Array.isArray(a) || !Array.isArray(b) || !a.length || !b.length) return 0;
  const len = Math.min(a.length, b.length);
  let sum = 0;
  for (let i = 0; i < len; i += 1) sum += a[i] * b[i];
  return sum;
}

function loadKnowledgeEmbeddingStore() {
  if (knowledgeEmbeddingStoreLoaded) return knowledgeEmbeddingStore;
  knowledgeEmbeddingStoreLoaded = true;
  try {
    if (!fs.existsSync(KNOWLEDGE_RAG_EMBEDDING_CACHE_FILE)) {
      knowledgeEmbeddingStore = { meta: {}, vectors: {} };
      return knowledgeEmbeddingStore;
    }
    const raw = fs.readFileSync(KNOWLEDGE_RAG_EMBEDDING_CACHE_FILE, "utf8");
    const json = JSON.parse(raw);
    const vectors = {};
    if (json?.vectors && typeof json.vectors === "object") {
      for (const [id, row] of Object.entries(json.vectors)) {
        const vector = sanitizeEmbeddingVector(row?.vector);
        if (!vector) continue;
        vectors[id] = {
          hash: normalizeSnippet(row?.hash, 96),
          model: normalizeSnippet(row?.model, 96),
          dimensions: Math.max(0, Number(row?.dimensions || vector.length)),
          norm: Number(row?.norm || vectorNorm(vector)),
          updatedAt: Math.max(0, Number(row?.updatedAt || 0)),
          vector,
        };
      }
    }
    knowledgeEmbeddingStore = {
      meta: json?.meta && typeof json.meta === "object" ? json.meta : {},
      vectors,
    };
  } catch (_err) {
    knowledgeEmbeddingStore = { meta: {}, vectors: {} };
  }
  return knowledgeEmbeddingStore;
}

function persistKnowledgeEmbeddingStore() {
  try {
    const store = loadKnowledgeEmbeddingStore();
    const payload = JSON.stringify(store);
    const tmpPath = `${KNOWLEDGE_RAG_EMBEDDING_CACHE_FILE}.tmp`;
    fs.writeFileSync(tmpPath, payload);
    fs.renameSync(tmpPath, KNOWLEDGE_RAG_EMBEDDING_CACHE_FILE);
  } catch (_err) {
    // Non-fatal: retrieval keeps running with in-memory vectors.
  }
  // T07d: dual-write to the persistence adapter when configured.
  // One row per embedding id keeps the table append-friendly for
  // future incremental updates. Errors are logged and non-blocking.
  if (sharedPersistence && typeof sharedPersistence.put === "function") {
    try {
      const store = loadKnowledgeEmbeddingStore();
      const vectors = store?.vectors || {};
      for (const [id, row] of Object.entries(vectors)) {
        void Promise.resolve(sharedPersistence.put({
          domain: "knowledge_embeddings",
          key: id,
          value: row,
        })).catch((err) => {
          console.error(`[knowledge_embeddings] adapter put failed for ${id}:`, err?.message || err);
        });
      }
    } catch (err) {
      console.error("[knowledge_embeddings] adapter dual-write failed:", err?.message || err);
    }
  }
}

// T07d: load embedding rows from the persistence adapter.
// Called as a fallback when the legacy JSON cache file is missing or
// empty. Returns true if any rows were loaded into the in-memory map.
async function loadKnowledgeEmbeddingStoreFromAdapter() {
  if (!sharedPersistence || typeof sharedPersistence.list !== "function") return false;
  let records;
  try {
    records = await sharedPersistence.list({ domain: "knowledge_embeddings", limit: 10_000 });
  } catch (err) {
    console.error("[knowledge_embeddings] adapter list failed:", err?.message || err);
    return false;
  }
  if (!Array.isArray(records) || records.length === 0) return false;
  knowledgeEmbeddingStoreLoaded = true;
  const vectors = {};
  for (const { key, value } of records) {
    const vector = sanitizeEmbeddingVector(value?.vector);
    if (!vector) continue;
    vectors[key] = {
      hash: normalizeSnippet(value?.hash, 96),
      model: normalizeSnippet(value?.model, 96),
      dimensions: Math.max(0, Number(value?.dimensions || vector.length)),
      norm: Number(value?.norm || vectorNorm(vector)),
      updatedAt: Math.max(0, Number(value?.updatedAt || 0)),
      vector,
    };
  }
  knowledgeEmbeddingStore = { meta: knowledgeEmbeddingStore?.meta || {}, vectors };
  return true;
}

function buildKnowledgeCardEmbeddingText(card) {
  return [
    `[topic] ${card.topic}`,
    `[title] ${card.title}`,
    `[tags] ${(Array.isArray(card.tags) ? card.tags.join(", ") : "") || "none"}`,
    `[body] ${card.body}`,
  ].join("\n");
}

async function fetchKnowledgeEmbeddings(inputs, { timeoutMs } = {}) {
  if (!OPENAI_API_KEY) return null;
  const list = Array.isArray(inputs) ? inputs : [inputs];
  const cleanInputs = list
    .map((item) => String(item || "").trim())
    .filter(Boolean);
  if (!cleanInputs.length) return null;

  const body = {
    model: KNOWLEDGE_RAG_EMBEDDING_MODEL,
    input: cleanInputs,
  };
  if (KNOWLEDGE_RAG_EMBEDDING_MODEL.startsWith("text-embedding-3")) {
    body.dimensions = KNOWLEDGE_RAG_EMBEDDING_DIMENSIONS;
  }

  const resp = await fetchWithTimeout(
    "https://api.openai.com/v1/embeddings",
    {
      method: "POST",
      headers: {
        Authorization: `Bearer ${OPENAI_API_KEY}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify(body),
    },
    Math.max(400, Number(timeoutMs || KNOWLEDGE_RAG_EMBEDDING_TIMEOUT_MS))
  );
  if (!resp.ok) {
    const text = await resp.text();
    const err = new Error(text || "Embedding request failed.");
    err.stage = "knowledge_embedding";
    err.status = resp.status;
    throw err;
  }
  const json = await resp.json();
  const rows = Array.isArray(json?.data) ? json.data : [];
  if (!rows.length) return null;

  const vectors = rows
    .map((row) => sanitizeEmbeddingVector(row?.embedding))
    .filter(Boolean);
  return vectors.length ? vectors : null;
}

function getQueryEmbeddingCacheKey(query) {
  const base = [
    KNOWLEDGE_RAG_EMBEDDING_MODEL,
    KNOWLEDGE_RAG_EMBEDDING_DIMENSIONS,
    String(query || "").trim().toLowerCase(),
  ].join("|");
  return hashSha256(base);
}

function setCachedQueryEmbedding(key, value) {
  if (!key) return;
  if (knowledgeQueryEmbeddingCache.has(key)) {
    knowledgeQueryEmbeddingCache.delete(key);
  }
  knowledgeQueryEmbeddingCache.set(key, value);
  while (knowledgeQueryEmbeddingCache.size > KNOWLEDGE_RAG_QUERY_CACHE_MAX) {
    const firstKey = knowledgeQueryEmbeddingCache.keys().next().value;
    if (!firstKey) break;
    knowledgeQueryEmbeddingCache.delete(firstKey);
  }
}

async function getKnowledgeQueryEmbedding(query, { timeoutMs } = {}) {
  const clean = String(query || "").trim();
  if (!clean) return null;
  if (!KNOWLEDGE_RAG_EMBEDDINGS_ENABLED || !OPENAI_API_KEY) return null;
  const now = Date.now();
  if (now < knowledgeSemanticBackoffUntil) return null;

  const key = getQueryEmbeddingCacheKey(clean);
  const cached = knowledgeQueryEmbeddingCache.get(key);
  if (cached?.vector && Number.isFinite(cached?.norm) && cached.norm > 0) {
    return cached;
  }

  try {
    const vectors = await fetchKnowledgeEmbeddings([clean], { timeoutMs });
    const vector = sanitizeEmbeddingVector(vectors?.[0]);
    if (!vector) return null;
    const payload = { vector, norm: vectorNorm(vector) };
    if (payload.norm <= 0) return null;
    setCachedQueryEmbedding(key, payload);
    return payload;
  } catch (_err) {
    knowledgeSemanticBackoffUntil = Date.now() + KNOWLEDGE_RAG_EMBEDDING_BACKOFF_MS;
    return null;
  }
}

async function ensureKnowledgeEmbeddingsForCards(cards, { timeoutMs } = {}) {
  if (!KNOWLEDGE_RAG_EMBEDDINGS_ENABLED || !OPENAI_API_KEY) return { updated: 0 };
  const now = Date.now();
  if (now < knowledgeSemanticBackoffUntil) return { updated: 0 };

  const store = loadKnowledgeEmbeddingStore();
  const missing = [];

  for (const card of cards) {
    if (!card || card.source === "memory") continue;
    const text = buildKnowledgeCardEmbeddingText(card);
    const hash = hashSha256(text);
    const existing = store.vectors?.[card.id];
    const upToDate = existing &&
      String(existing.hash || "") === hash &&
      String(existing.model || "") === KNOWLEDGE_RAG_EMBEDDING_MODEL &&
      Number(existing.dimensions || 0) === KNOWLEDGE_RAG_EMBEDDING_DIMENSIONS &&
      Array.isArray(existing.vector) &&
      existing.vector.length > 0;
    if (upToDate) continue;
    missing.push({ card, text, hash });
  }

  if (!missing.length) return { updated: 0 };

  let updated = 0;
  try {
    for (let i = 0; i < missing.length; i += KNOWLEDGE_RAG_EMBEDDING_BATCH_SIZE) {
      const batch = missing.slice(i, i + KNOWLEDGE_RAG_EMBEDDING_BATCH_SIZE);
      const vectors = await fetchKnowledgeEmbeddings(
        batch.map((item) => item.text),
        { timeoutMs }
      );
      if (!Array.isArray(vectors) || vectors.length !== batch.length) continue;
      for (let j = 0; j < batch.length; j += 1) {
        const vector = sanitizeEmbeddingVector(vectors[j]);
        if (!vector) continue;
        const norm = vectorNorm(vector);
        if (norm <= 0) continue;
        const item = batch[j];
        store.vectors[item.card.id] = {
          hash: item.hash,
          model: KNOWLEDGE_RAG_EMBEDDING_MODEL,
          dimensions: KNOWLEDGE_RAG_EMBEDDING_DIMENSIONS,
          vector,
          norm,
          updatedAt: Date.now(),
        };
        updated += 1;
      }
    }
  } catch (_err) {
    knowledgeSemanticBackoffUntil = Date.now() + KNOWLEDGE_RAG_EMBEDDING_BACKOFF_MS;
  }

  if (updated > 0) {
    store.meta = {
      model: KNOWLEDGE_RAG_EMBEDDING_MODEL,
      dimensions: KNOWLEDGE_RAG_EMBEDDING_DIMENSIONS,
      updatedAt: Date.now(),
      cardsLoadedAt: knowledgeCardsLoadedAt,
    };
    persistKnowledgeEmbeddingStore();
  }
  return { updated };
}

async function warmupKnowledgeEmbeddingsOnBoot({ rid = "knowledge_warmup" } = {}) {
  if (knowledgeWarmupPromise) return knowledgeWarmupPromise;
  knowledgeWarmupPromise = (async () => {
    const startedAt = Date.now();
    if (!KNOWLEDGE_RAG_WARMUP_ON_BOOT) {
      console.log(`[${rid}] skipped reason=warmup_disabled`);
      return { updated: 0, total: 0, skipped: true };
    }
    if (!KNOWLEDGE_RAG_ENABLED || !KNOWLEDGE_RAG_EMBEDDINGS_ENABLED) {
      console.log(`[${rid}] skipped reason=rag_or_embeddings_disabled`);
      return { updated: 0, total: 0, skipped: true };
    }
    if (!OPENAI_API_KEY) {
      console.log(`[${rid}] skipped reason=missing_api_key`);
      return { updated: 0, total: 0, skipped: true };
    }
    const cards = loadKnowledgeCards()
      .filter((card) => card && card.source !== "memory")
      .slice(0, KNOWLEDGE_RAG_WARMUP_MAX_CARDS);
    if (!cards.length) {
      console.log(`[${rid}] skipped reason=no_cards`);
      return { updated: 0, total: 0, skipped: true };
    }
    const result = await ensureKnowledgeEmbeddingsForCards(cards, {
      timeoutMs: KNOWLEDGE_RAG_WARMUP_TIMEOUT_MS,
    });
    const elapsedMs = Date.now() - startedAt;
    const updated = Math.max(0, Number(result?.updated || 0));
    console.log(
      `[${rid}] done cards=${cards.length} updated=${updated} elapsed_ms=${elapsedMs} ` +
      `model=${KNOWLEDGE_RAG_EMBEDDING_MODEL} dims=${KNOWLEDGE_RAG_EMBEDDING_DIMENSIONS} cache=${path.basename(KNOWLEDGE_RAG_EMBEDDING_CACHE_FILE)}`
    );
    return { updated, total: cards.length, skipped: false };
  })();
  try {
    return await knowledgeWarmupPromise;
  } finally {
    knowledgeWarmupPromise = null;
  }
}

function semanticSimilarityForCard(card, queryVector, queryNorm) {
  if (!card || !Array.isArray(queryVector) || !queryNorm) return null;
  const store = loadKnowledgeEmbeddingStore();
  const row = store.vectors?.[card.id];
  if (!row || !Array.isArray(row.vector) || !row.vector.length) return null;
  const denom = Number(row.norm || vectorNorm(row.vector)) * queryNorm;
  if (denom <= 0) return null;
  const similarity = dotProduct(row.vector, queryVector) / denom;
  if (!Number.isFinite(similarity)) return null;
  return Math.max(-1, Math.min(1, similarity));
}

function buildKnowledgeContextLines(cards, maxChars = KNOWLEDGE_RAG_CONTEXT_MAX_CHARS) {
  const lines = [];
  let total = 0;
  for (const card of cards) {
    const line = `${lines.length + 1}. [${card.topic}] ${card.title}: ${normalizeSnippet(card.body, KNOWLEDGE_RAG_CARD_BODY_MAX_CHARS)}${card.source === "memory" ? " (user context)" : ""}`;
    if (!line.trim()) continue;
    if (total > 0 && (total + line.length + 1) > maxChars) break;
    lines.push(line);
    total += line.length + 1;
  }
  return lines;
}

async function retrieveKnowledgeCards(query, {
  maxItems = KNOWLEDGE_RETRIEVAL_MAX_ITEMS,
  minScore = KNOWLEDGE_RETRIEVAL_MIN_SCORE,
  flags = null,
  turnPlanner = null,
  memory = null,
  rid = "knowledge",
} = {}) {
  const startedAt = Date.now();
  const q = String(query || "").trim().toLowerCase();
  if (!KNOWLEDGE_RETRIEVAL_ENABLED || !q) {
    return {
      cards: [],
      meta: {
        retrievalMs: Date.now() - startedAt,
        semanticUsed: false,
        reason: "disabled_or_empty",
        forceSemantic: false,
      },
    };
  }

  const profile = deriveKnowledgeQueryProfile(q, { flags, turnPlanner });
  const forceSemantic = Boolean(
    KNOWLEDGE_RAG_FORCE_SEMANTIC_ON_KNOWLEDGE &&
    String(turnPlanner?.intent || "").toLowerCase() === "knowledge_answer"
  );
  const staticCards = loadKnowledgeCards();
  const memoryCards = buildKnowledgeMemoryCards(memory, 6);
  const corpus = [...staticCards, ...memoryCards];
  if (!corpus.length) {
    return {
      cards: [],
      meta: {
        retrievalMs: Date.now() - startedAt,
        semanticUsed: false,
        reason: "no_corpus",
        forceSemantic,
        profile,
      },
    };
  }

  const lexicalRanked = corpus
    .map((card) => ({
      ...card,
      lexicalScore: scoreKnowledgeCardLexical(card, profile),
    }))
    .filter((row) => row.lexicalScore > 0.05)
    .sort((a, b) => b.lexicalScore - a.lexicalScore);

  if (!lexicalRanked.length) {
    return {
      cards: [],
      meta: {
        retrievalMs: Date.now() - startedAt,
        semanticUsed: false,
        reason: "no_lexical_hits",
        forceSemantic,
        profile,
      },
    };
  }

  const prefilter = lexicalRanked.slice(0, KNOWLEDGE_RAG_PREFILTER_MAX);
  const semanticMap = new Map();
  let semanticUsed = false;
  let semanticReason = "disabled";

  if (
    KNOWLEDGE_RAG_ENABLED &&
    KNOWLEDGE_RAG_EMBEDDINGS_ENABLED &&
    OPENAI_API_KEY &&
    Date.now() >= knowledgeSemanticBackoffUntil
  ) {
    const elapsed = Date.now() - startedAt;
    const remainingBudget = Math.max(0, KNOWLEDGE_RAG_QUERY_TIMEOUT_MS - elapsed);
    if (forceSemantic || remainingBudget >= 250) {
      const forcedTimeout = Math.max(
        180,
        Math.min(KNOWLEDGE_RAG_EMBEDDING_TIMEOUT_MS, KNOWLEDGE_RAG_FORCE_SEMANTIC_TIMEOUT_MS)
      );
      const queryTimeout = forceSemantic
        ? forcedTimeout
        : Math.max(250, Math.min(remainingBudget, KNOWLEDGE_RAG_EMBEDDING_TIMEOUT_MS));
      const queryEmbedding = await getKnowledgeQueryEmbedding(q, {
        timeoutMs: queryTimeout,
      });
      if (queryEmbedding?.vector && queryEmbedding?.norm > 0) {
        const embedCandidates = prefilter
          .filter((row) => row.source !== "memory")
          .slice(0, KNOWLEDGE_RAG_EMBED_TOPK);
        const elapsedAfterQuery = Date.now() - startedAt;
        const remainingAfterQuery = Math.max(0, KNOWLEDGE_RAG_QUERY_TIMEOUT_MS - elapsedAfterQuery);
        const ensureTimeout = forceSemantic
          ? forcedTimeout
          : Math.max(250, Math.min(remainingAfterQuery, KNOWLEDGE_RAG_EMBEDDING_TIMEOUT_MS));
        if (embedCandidates.length && (forceSemantic || remainingAfterQuery >= 250)) {
          await ensureKnowledgeEmbeddingsForCards(embedCandidates, {
            timeoutMs: ensureTimeout,
          });
        }
        for (const row of prefilter) {
          const sim = semanticSimilarityForCard(row, queryEmbedding.vector, queryEmbedding.norm);
          if (sim == null) continue;
          semanticMap.set(row.id, sim);
        }
        semanticUsed = semanticMap.size > 0;
        semanticReason = semanticUsed ? "ok" : "no_vectors";
      } else {
        semanticReason = "query_embedding_unavailable";
      }
    } else {
      semanticReason = "budget_exhausted";
    }
  } else if (!KNOWLEDGE_RAG_EMBEDDINGS_ENABLED) {
    semanticReason = "embeddings_disabled";
  } else if (!OPENAI_API_KEY) {
    semanticReason = "missing_api_key";
  } else if (Date.now() < knowledgeSemanticBackoffUntil) {
    semanticReason = "backoff";
  }

  const lexicalPeak = Math.max(0.0001, prefilter[0]?.lexicalScore || 0.0001);
  const scored = prefilter.map((row) => {
    const lexicalNorm = Math.max(0, row.lexicalScore / lexicalPeak);
    const semanticRaw = semanticMap.get(row.id);
    const semanticNorm = semanticRaw == null ? 0 : Math.max(0, (semanticRaw + 1) / 2);
    const topicBoost = Math.max(0, Number(profile.topicWeights?.[row.topic] || 0));
    const memoryBoost = row.source === "memory"
      ? KNOWLEDGE_RAG_MEMORY_WEIGHT * (0.6 + (Math.max(0, Math.min(1, Number(row.salience || 0.4))) * 0.4))
      : 0;

    let score =
      (lexicalNorm * KNOWLEDGE_RAG_LEXICAL_WEIGHT) +
      (semanticNorm * KNOWLEDGE_RAG_SEMANTIC_WEIGHT) +
      (topicBoost * KNOWLEDGE_RAG_TOPIC_WEIGHT) +
      memoryBoost;

    if (profile.isRelational && KNOWLEDGE_RELATIONAL_TOPICS.has(row.topic)) score += 0.10;
    if (profile.isFoundational && textContainsAny(row.topic, ["movies", "art_history", "philosophy", "learning"])) {
      score += 0.05;
    }

    return {
      ...row,
      score,
      semanticScore: semanticRaw == null ? null : semanticRaw,
    };
  });

  const scoreFloor = Math.max(0.16, Math.min(1.15, Number(minScore || KNOWLEDGE_RETRIEVAL_MIN_SCORE)));
  const filtered = scored
    .filter((row) => row.score >= scoreFloor)
    .sort((a, b) => b.score - a.score);
  const selected = (filtered.length ? filtered : scored.sort((a, b) => b.score - a.score))
    .slice(0, Math.max(1, Math.min(12, Number(maxItems || KNOWLEDGE_RETRIEVAL_MAX_ITEMS))));

  const cards = selected.map((row) => ({
    id: row.id,
    topic: row.topic,
    title: row.title,
    body: row.body,
    tags: row.tags,
    level: row.level,
    source: row.source,
    score: Number(row.score.toFixed(4)),
    lexicalScore: Number(row.lexicalScore.toFixed(4)),
    semanticScore: row.semanticScore == null ? null : Number(row.semanticScore.toFixed(4)),
  }));

  return {
    cards,
    meta: {
      retrievalMs: Date.now() - startedAt,
      semanticUsed,
      semanticReason,
      forceSemantic,
      profile,
      corpusSize: corpus.length,
      prefilterSize: prefilter.length,
      memoryCards: memoryCards.length,
    },
  };
}

async function buildKnowledgeRetrievalAddendum({
  turnPlanner,
  routingPlan,
  transcript,
  flags = null,
  memory = null,
  rid = "knowledge",
}) {
  const intent = String(turnPlanner?.intent || "");
  if (intent !== "knowledge_answer") {
    return {
      addendum: "",
      cards: [],
      meta: { retrievalMs: 0, semanticUsed: false, semanticReason: "inactive", forceSemantic: false },
    };
  }

  const retrieval = await retrieveKnowledgeCards(transcript, {
    maxItems: KNOWLEDGE_RETRIEVAL_MAX_ITEMS,
    minScore: KNOWLEDGE_RETRIEVAL_MIN_SCORE,
    flags,
    turnPlanner,
    memory,
    rid,
  });
  const cards = Array.isArray(retrieval?.cards) ? retrieval.cards : [];
  const meta = retrieval?.meta && typeof retrieval.meta === "object"
    ? retrieval.meta
    : { retrievalMs: 0, semanticUsed: false, semanticReason: "unknown", forceSemantic: false };
  const topicHints = Object.keys(meta?.profile?.topicWeights || {});
  const topicSummary = topicHints.length ? topicHints.join(", ") : "general";

  if (!cards.length) {
    return {
      addendum: `
KNOWLEDGE MODE:
- mode=knowledge_answer (no retrieval hits).
- retrieval_stack=hybrid_rag(lexical+semantic+memory) semantic=${meta.semanticUsed ? "on" : "off"} forced=${meta.forceSemantic ? "1" : "0"} reason=${meta.semanticReason || "n/a"} topics=${topicSummary}
- keep structure: baseline answer first, then one deeper layer, then one concrete example.
- if uncertain on dates/names, say uncertainty briefly instead of inventing.
- keep emotional companion warmth, but prioritize factual precision and scope discipline.
- recommendation_scope_lock=only recommend items relevant to the original ask.
`.trim(),
      cards: [],
      meta,
    };
  }

  const contextLines = buildKnowledgeContextLines(cards, KNOWLEDGE_RAG_CONTEXT_MAX_CHARS);
  return {
    addendum: `
KNOWLEDGE MODE:
- mode=knowledge_answer_with_retrieval.
- retrieval_stack=hybrid_rag(lexical+semantic+memory) semantic=${meta.semanticUsed ? "on" : "off"} forced=${meta.forceSemantic ? "1" : "0"} reason=${meta.semanticReason || "n/a"} topics=${topicSummary}
- keep structure: baseline answer first, then one deeper layer, then one concrete example.
- do not drift into unrelated recommendations.
- separate concern: factual layer first, emotional companion tone second.
- if cards include source=memory, use as personalization context only (never as external fact citation).
- retrieved_context:
${contextLines.join("\n")}
`.trim(),
    cards,
    meta,
  };
}

function hash01(str) {
  let h = 2166136261;
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = Math.imul(h, 16777619);
  }
  return (h >>> 0) / 4294967295;
}

