function countWords(text) {
  return String(text || "")
    .trim()
    .split(/\s+/)
    .filter(Boolean)
    .length;
}

function inferMelancholyLane(transcript) {
  const t = String(transcript || "").toLowerCase();
  if (
    textContainsAny(t, [
      "love", "relationship", "my ex", "ex partner", "ex-partner", "goodbye", "timing",
      "miss", "heart", "romance", "unfinished", "they", "him", "her",
    ])
  ) {
    return "romantic";
  }
  if (
    textContainsAny(t, [
      "lonely", "meaning", "purpose", "unreal", "observe", "understood", "truth", "noise", "empty",
      "world", "exist",
    ])
  ) {
    return "existential";
  }
  return "reflective";
}

function detectMelancholyTrigger({ transcript, vibe, lateNightMode }) {
  const t = String(transcript || "").toLowerCase().trim();
  if (!t) {
    return { shouldUse: false, reason: "none", lane: "reflective" };
  }

  const words = countWords(t);
  const shortPause = words <= 4;

  const unsure = textContainsAny(t, [
    "i don't know", "idk", "not sure", "no idea", "i dunno", "i dont know", "unsure",
  ]);
  const emotionalDip = textContainsAny(t, [
    "weird", "off", "empty", "numb", "stuck", "lost", "drained", "tired", "low", "sad", "disconnected",
  ]);
  const vulnerabilityFollowup =
    vibe === "vulnerable" &&
    textContainsAny(t, ["miss", "hurt", "grief", "alone", "can't sleep", "cant sleep", "goodbye", "lonely"]);

  const lateNightCue =
    lateNightMode &&
    (unsure || emotionalDip || shortPause || vibe === "vulnerable");

  let reason = "none";
  if (unsure) reason = "unsure";
  else if (lateNightCue) reason = "late_night";
  else if (vulnerabilityFollowup) reason = "vulnerability_followup";
  else if (emotionalDip) reason = "emotional_dip";
  else if (shortPause) reason = "pause";

  const shouldUse = reason !== "none";
  const lane = inferMelancholyLane(t);

  return { shouldUse, reason, lane };
}

function buildMelancholySeedAddendum({ rid, transcript, vibe, lateNightMode }) {
  const decision = detectMelancholyTrigger({ transcript, vibe, lateNightMode });
  if (!decision.shouldUse) return "";

  const bank = MELANCHOLY_SEED_BANK[decision.lane] || MELANCHOLY_SEED_BANK.reflective;
  const seeds = pickSeedLines(bank, 3, `${rid}|melancholy|${decision.lane}|${transcript}`);

  return `
CINEMATIC INTIMACY SEEDS:
- trigger=${decision.reason} lane=${decision.lane}
- If natural, use at most one seed this turn as:
  1) opener after pause/uncertainty, or
  2) follow-up after vulnerability.
- Keep it friendly, warm, and emotionally available (never detached or avoidant).
- Prefer statement endings by default; if you use a reflective question, keep it to one.
Seed examples: ${seeds.join(" | ")}
`.trim();
}

function parseBoundedFloat(value, min, max) {
  const parsed = Number.parseFloat(String(value ?? "").trim());
  if (!Number.isFinite(parsed)) return null;
  return Math.max(min, Math.min(max, parsed));
}

function parseBoundedInt(value, min, max) {
  const parsed = Number.parseInt(String(value ?? "").trim(), 10);
  if (!Number.isFinite(parsed)) return null;
  return Math.max(min, Math.min(max, parsed));
}

function deriveDynamicVadThreshold({
  noiseFloorRms = 0,
  speechRms = 0,
  vadThresholdHint = null,
} = {}) {
  const hint = parseBoundedFloat(vadThresholdHint, TURN_END_GUARD_VAD_MIN_RMS, TURN_END_GUARD_VAD_MAX_RMS);
  if (hint != null) return hint;

  const noise = Math.max(0, Number(noiseFloorRms || 0));
  const speech = Math.max(0, Number(speechRms || 0));
  let threshold = TURN_END_GUARD_VAD_BASE_RMS;
  if (noise > 0) {
    threshold = Math.max(threshold, noise * TURN_END_GUARD_NOISE_MULTIPLIER);
  }
  if (speech > 0) {
    const speechFloor = speech * 0.18;
    threshold = Math.max(threshold, speechFloor);
  }
  return Math.max(
    TURN_END_GUARD_VAD_MIN_RMS,
    Math.min(TURN_END_GUARD_VAD_MAX_RMS, threshold)
  );
}

function deriveDynamicTailBoostMs({ dynamicVadThreshold = 0 } = {}) {
  const threshold = Math.max(0, Number(dynamicVadThreshold || 0));
  if (!TURN_END_GUARD_DYNAMIC_NOISE_ENABLED) return 0;
  if (!(threshold > 0) || !(TURN_END_GUARD_VAD_BASE_RMS > 0)) return 0;
  const ratio = threshold / TURN_END_GUARD_VAD_BASE_RMS;
  if (!(ratio > 1)) return 0;
  const boost = Math.round((ratio - 1) * 260);
  return Math.max(0, Math.min(TURN_END_GUARD_DYNAMIC_TAIL_BOOST_MAX_MS, boost));
}

function estimateSttConfidence(sttJson, transcript = "") {
  const stt = sttJson && typeof sttJson === "object" ? sttJson : {};
  const words = Array.isArray(stt.words) ? stt.words : [];
  const wordConf = words
    .map((w) => Number(w?.confidence))
    .filter((x) => Number.isFinite(x) && x >= 0 && x <= 1);
  if (wordConf.length >= 2) {
    const avg = wordConf.reduce((sum, x) => sum + x, 0) / wordConf.length;
    return clampUnit(avg, 0.55);
  }

  const segments = Array.isArray(stt.segments) ? stt.segments : [];
  const segScores = [];
  for (const seg of segments) {
    if (!seg || typeof seg !== "object") continue;
    const noSpeechProb = Number(seg.no_speech_prob);
    const avgLogprob = Number(seg.avg_logprob);
    let score = 0.55;
    if (Number.isFinite(noSpeechProb) && noSpeechProb >= 0 && noSpeechProb <= 1) {
      score = (score * 0.45) + ((1 - noSpeechProb) * 0.55);
    }
    if (Number.isFinite(avgLogprob) && avgLogprob <= 0) {
      const logNorm = Math.max(0, Math.min(1, 1 + (avgLogprob / 2.4)));
      score = (score * 0.60) + (logNorm * 0.40);
    }
    segScores.push(clampUnit(score, 0.55));
  }
  if (segScores.length) {
    const avg = segScores.reduce((sum, x) => sum + x, 0) / segScores.length;
    return clampUnit(avg, 0.55);
  }

  const text = String(transcript || "").trim();
  const wordCount = countWords(text);
  if (!text) return 0;
  if (wordCount <= 2) return 0.40;
  if (wordCount <= 5) return 0.52;
  if (wordCount >= 24) return 0.76;
  return 0.62;
}

function parseTurnTimingHints(reqBody, sttJson) {
  const audioDurationSecFromBody = parseBoundedFloat(
    reqBody?.audio_duration_sec ??
      reqBody?.audioDurationSec ??
      reqBody?.duration_sec ??
      reqBody?.durationSec,
    0,
    600
  );
  const audioDurationSecFromStt = parseBoundedFloat(sttJson?.duration, 0, 600);
  const speechMs = parseBoundedInt(
    reqBody?.speech_ms ?? reqBody?.speechMs ?? reqBody?.voice_ms ?? reqBody?.voiceMs,
    0,
    600_000
  );
  const tailSilenceMs = parseBoundedInt(
    reqBody?.tail_silence_ms ??
      reqBody?.tailSilenceMs ??
      reqBody?.silence_ms ??
      reqBody?.silenceMs ??
      reqBody?.end_silence_ms ??
      reqBody?.endSilenceMs,
    0,
    600_000
  );
  const noiseFloorRms = parseBoundedFloat(
    reqBody?.noise_floor_rms ??
      reqBody?.noiseFloorRms ??
      reqBody?.ambient_rms ??
      reqBody?.ambientRms,
    0,
    0.2
  );
  const speechRms = parseBoundedFloat(
    reqBody?.speech_rms ??
      reqBody?.voice_rms ??
      reqBody?.voiceRms ??
      reqBody?.rms,
    0,
    0.2
  );
  const vadThresholdHint = parseBoundedFloat(
    reqBody?.vad_threshold ??
      reqBody?.vadThreshold ??
      reqBody?.speech_threshold ??
      reqBody?.speechThreshold,
    TURN_END_GUARD_VAD_MIN_RMS,
    TURN_END_GUARD_VAD_MAX_RMS
  );
  const dynamicVadThreshold = deriveDynamicVadThreshold({
    noiseFloorRms,
    speechRms,
    vadThresholdHint,
  });

  return {
    audioDurationSec: audioDurationSecFromBody ?? audioDurationSecFromStt ?? 0,
    speechMs: speechMs ?? 0,
    tailSilenceMs: tailSilenceMs ?? 0,
    noiseFloorRms: noiseFloorRms ?? 0,
    speechRms: speechRms ?? 0,
    vadThresholdHint: vadThresholdHint ?? 0,
    dynamicVadThreshold,
    hasSpeechMs: speechMs != null,
    hasTailSilenceMs: tailSilenceMs != null,
    hasNoiseFloorRms: noiseFloorRms != null,
    hasSpeechRms: speechRms != null,
    hasVadThresholdHint: vadThresholdHint != null,
  };
}

function detectMidThoughtSignals(transcript) {
  const raw = String(transcript || "").trim();
  const lower = raw.toLowerCase();
  const words = countWords(raw);
  const terminal = /[.!?]["')\]]?$/.test(raw);
  const trailingContinuation = /\b(and|but|so|because|then|or|if|when|while|which|that|to|like|anyway|plus|also)\s*$/i.test(lower) ||
    /\b(you know|i mean)\s*$/i.test(lower);
  const trailingCommaOrDash = /[,;:-]\s*$/.test(raw) || /(\.\.\.|…)\s*$/.test(raw);
  const danglingQuoteOrParen = /["'(]\s*$/.test(raw);
  const startsWithContinuation = /^(and|so|but|because|then|anyway|plus|also)\b/i.test(lower);
  const midThought =
    !terminal &&
    (trailingContinuation ||
      trailingCommaOrDash ||
      danglingQuoteOrParen ||
      (startsWithContinuation && words >= 8));

  return {
    words,
    terminal,
    trailingContinuation,
    trailingCommaOrDash,
    danglingQuoteOrParen,
    startsWithContinuation,
    midThought,
  };
}

function isLikelyAmbiguousLowConfidenceUtterance(transcript = "", sttConfidence = null) {
  const raw = String(transcript || "").trim();
  if (!raw) return false;
  const lower = raw.toLowerCase();
  const words = countWords(raw);
  const conf = parseBoundedFloat(sttConfidence, 0, 1);
  const confidence = conf == null ? 0.40 : conf;

  if (words > 3) return false;
  if (confidence >= 0.56) return false;

  const explicitQuestion =
    /\?$/.test(raw) ||
    /\b(can you|could you|would you|should i|what|why|how|when|where|who)\b/i.test(lower);
  if (explicitQuestion) return false;

  if (textContainsAny(lower, [
    "yes", "yeah", "yep", "no", "nope", "nah",
    "thanks", "thank you", "ok", "okay",
    "stop", "pause", "continue", "go ahead",
    "goodbye", "bye", "talk later", "love you",
    "hi", "hello", "hey",
  ])) {
    return false;
  }

  return true;
}

function buildLowConfidenceClarificationPrompt(transcript = "") {
  const anchor = pickContinuityAnchor(transcript) || extractAnchorTerms(transcript)[0] || "";
  if (anchor) {
    return `I caught only part of that, maybe "${anchor}". Say it again in one sentence, and I'll respond exactly to what you mean.`;
  }
  return "I caught only part of that. Say it again in one sentence, and I'll respond exactly to what you mean.";
}

function shouldHoldForContinuation({ transcript, reqBody, sttJson, memory, sttConfidence = null }) {
  const holdStreak = Math.max(0, Number(memory?.continuationHoldCount || 0));
  const maxHoldReached = holdStreak >= TURN_END_GUARD_MAX_CONSECUTIVE_HOLDS;
  const timing = parseTurnTimingHints(reqBody, sttJson);
  const cues = detectMidThoughtSignals(transcript);
  const raw = String(transcript || "").trim();
  const lower = raw.toLowerCase();
  const hasTimingTelemetry =
    Boolean(timing.hasSpeechMs) ||
    Boolean(timing.hasTailSilenceMs) ||
    (Number(timing.audioDurationSec || 0) > 0);
  const explicitTurnDone = textContainsAny(lower, [
    "that is all",
    "that's all",
    "thats all",
    "that's it",
    "thats it",
    "your turn",
    "go ahead",
    "you can answer now",
  ]);
  const explicitQuestion = /\?$/.test(raw) || /\b(can you|could you|would you|should i|what|why|how)\b/i.test(raw);
  const shortUtterance = cues.words > 0 && cues.words <= 6;
  const confidenceHint = parseBoundedFloat(sttConfidence, 0, 1);
  const effectiveConfidence = confidenceHint != null
    ? confidenceHint
    : estimateSttConfidence(sttJson, transcript);
  const lowConfidenceShortUtterance =
    shortUtterance &&
    !explicitQuestion &&
    !explicitTurnDone &&
    cues.words <= 2 &&
    effectiveConfidence < 0.30;
  const likelyCompleteShortQuestion =
    explicitQuestion &&
    cues.terminal &&
    cues.words <= Math.max(14, TURN_END_GUARD_MIN_WORDS + 2) &&
    !cues.midThought &&
    !cues.trailingContinuation &&
    !cues.trailingCommaOrDash;

  // Never hold obvious completed asks; this prevents "silent" feeling on direct questions.
  if (explicitTurnDone || likelyCompleteShortQuestion) {
    return {
      hold: false,
      reason: explicitTurnDone ? "explicit_turn_complete" : "complete_short_question",
      confidence: 0,
      holdStreak,
      likelyLongStory: false,
      effectiveTailSilenceThreshold: TURN_END_GUARD_TAIL_SILENCE_MS,
      dynamicTailBoostMs: 0,
      ...timing,
      ...cues,
    };
  }

  // For very short low-confidence clips, keep listening to avoid generic one-word loops.
  if (TURN_END_GUARD_ENABLED && !maxHoldReached && lowConfidenceShortUtterance) {
    return {
      hold: true,
      reason: "low_confidence_short_utterance",
      confidence: Math.max(0, Math.min(0.95, 1 - effectiveConfidence)),
      holdStreak,
      likelyLongStory: false,
      effectiveTailSilenceThreshold: TURN_END_GUARD_TAIL_SILENCE_MS,
      dynamicTailBoostMs: 0,
      ...timing,
      ...cues,
    };
  }

  // Don't continuation-hold short utterances that are clear enough to answer.
  if (shortUtterance) {
    return {
      hold: false,
      reason: "short_utterance",
      confidence: 0,
      holdStreak,
      likelyLongStory: false,
      effectiveTailSilenceThreshold: TURN_END_GUARD_TAIL_SILENCE_MS,
      dynamicTailBoostMs: 0,
      ...timing,
      ...cues,
    };
  }

  const likelyLongStory =
    cues.words >= TURN_END_GUARD_LONG_STORY_WORDS ||
    (timing.hasSpeechMs && timing.speechMs >= TURN_END_GUARD_LONG_STORY_SPEECH_MS);
  const minTailForLongSpeech =
    timing.hasSpeechMs && timing.speechMs >= TURN_END_GUARD_LONG_SPEECH_MS
      ? Math.max(900, TURN_END_GUARD_TAIL_SILENCE_MS)
      : TURN_END_GUARD_TAIL_SILENCE_MS;
  let effectiveTailSilenceThreshold = likelyLongStory
    ? Math.max(minTailForLongSpeech, TURN_END_GUARD_LONG_STORY_TAIL_SILENCE_MS)
    : minTailForLongSpeech;
  const dynamicTailBoostMs = deriveDynamicTailBoostMs({
    dynamicVadThreshold: timing.dynamicVadThreshold,
  });
  if (TURN_END_GUARD_DYNAMIC_NOISE_ENABLED) {
    effectiveTailSilenceThreshold += dynamicTailBoostMs;
  }

  const shortTailAfterLongSpeech =
    hasTimingTelemetry &&
    timing.hasSpeechMs &&
    timing.hasTailSilenceMs &&
    timing.speechMs >= Math.min(TURN_END_GUARD_LONG_SPEECH_MS, TURN_END_GUARD_LONG_STORY_SPEECH_MS) &&
    timing.tailSilenceMs > 0 &&
    timing.tailSilenceMs < effectiveTailSilenceThreshold;

  const syntaxMidThoughtStrong =
    cues.midThought &&
    cues.trailingContinuation &&
    cues.words >= Math.max(10, TURN_END_GUARD_MIN_WORDS);

  const syntaxMidThought =
    syntaxMidThoughtStrong;

  const longClipNoTerminal =
    hasTimingTelemetry &&
    !cues.terminal &&
    timing.audioDurationSec >= TURN_END_GUARD_MIN_AUDIO_SECONDS &&
    cues.words >= TURN_END_GUARD_MIN_WORDS &&
    (cues.trailingContinuation || cues.trailingCommaOrDash || cues.danglingQuoteOrParen);
  const longStoryTailLikelyCutoff =
    hasTimingTelemetry &&
    likelyLongStory &&
    !cues.terminal &&
    timing.hasTailSilenceMs &&
    timing.tailSilenceMs > 0 &&
    timing.tailSilenceMs < (effectiveTailSilenceThreshold + 250);
  const possibleEarlyCutoff =
    hasTimingTelemetry &&
    !cues.terminal &&
    cues.words >= Math.max(TURN_END_GUARD_MIN_WORDS + 4, 14) &&
    timing.hasTailSilenceMs &&
    timing.tailSilenceMs > 0 &&
    timing.tailSilenceMs < (effectiveTailSilenceThreshold + 160);
  const longStoryAwaitingTailTelemetry =
    hasTimingTelemetry &&
    likelyLongStory &&
    !cues.terminal &&
    timing.hasSpeechMs &&
    timing.speechMs >= TURN_END_GUARD_LONG_STORY_SPEECH_MS &&
    !timing.hasTailSilenceMs;

  let confidence = 0;
  if (shortTailAfterLongSpeech) confidence += 0.62;
  if (syntaxMidThought) confidence += 0.42;
  if (longClipNoTerminal) confidence += 0.24;
  if (longStoryTailLikelyCutoff) confidence += 0.36;
  if (possibleEarlyCutoff) confidence += 0.30;
  if (longStoryAwaitingTailTelemetry) confidence += 0.28;
  confidence = Math.max(0, Math.min(0.98, confidence));

  let hold = false;
  let reason = "none";
  if (TURN_END_GUARD_ENABLED && !maxHoldReached) {
    if (shortTailAfterLongSpeech) {
      hold = true;
      reason = "short_tail_after_long_speech";
    } else if (longStoryTailLikelyCutoff && confidence >= 0.50) {
      hold = true;
      reason = "long_story_tail_short";
    } else if (possibleEarlyCutoff && confidence >= 0.52) {
      hold = true;
      reason = "possible_early_cutoff";
    } else if (longStoryAwaitingTailTelemetry && confidence >= 0.56) {
      hold = true;
      reason = "long_story_wait_tail_signal";
    } else if (syntaxMidThought && confidence >= 0.56) {
      hold = true;
      reason = "mid_thought_syntax";
    } else if (longClipNoTerminal && confidence >= 0.55) {
      hold = true;
      reason = "likely_cutoff_long_clip";
    }
  } else if (maxHoldReached) {
    reason = "hold_budget_exhausted";
  }

  return {
    hold,
    reason,
    confidence,
    holdStreak,
    likelyLongStory,
    effectiveTailSilenceThreshold,
    dynamicTailBoostMs,
    ...timing,
    ...cues,
  };
}

function stageGuidanceLine(stage) {
  switch (stage) {
    case 1:
      return "stage 1 -> warm and light, focus on safety and basic reflection.";
    case 2:
      return "stage 2 -> curious and grounded, gently surface patterns.";
    case 3:
      return "stage 3 -> deeper emotional naming and practical regulation.";
    case 4:
      return "stage 4 -> more challenge + accountability, still warm.";
    default:
      return "stage 5 -> intimate reflective coaching with nuanced subtext and strong containment.";
  }
}

function inferStageFromSystem(systemPrompt) {
  const s = String(systemPrompt || "");
  if (/Stage\s*3|\bTension\b/i.test(s)) return 3;
  if (/Stage\s*2|\bRecognition\b/i.test(s)) return 2;
  return 1;
}

