function detectMotivationModeSignal(transcript, flags = null, memory = null) {
  const t = String(transcript || "").toLowerCase().trim();
  if (!t) {
    return {
      active: false,
      explicit: false,
      depleted: false,
      progressFollowup: false,
      reason: "none",
    };
  }
  const explicit = textContainsAny(t, MOTIVATION_MODE_EXPLICIT_PHRASES);
  const depleted = textContainsAny(t, MOTIVATION_MODE_DEPLETED_PHRASES);
  const agencyAsk = textContainsAny(t, [
    "help me",
    "what do i do",
    "what should i do",
    "next step",
    "one step",
    "push through",
    "show up",
  ]);
  const pendingFollowup = Boolean(memory?.motivationFollowupPending);
  const progressCue = textContainsAny(t, MOTIVATION_MODE_PROGRESS_PHRASES);
  const followupCue = textContainsAny(t, [
    "quick update",
    "update",
    "we talked about",
    "like we planned",
    "from before",
    "again",
  ]);
  const taskCue = textContainsAny(t, [
    "email",
    "outline",
    "task",
    "step",
    "draft",
    "sent",
    "finished",
    "didn't do",
    "didnt do",
  ]);
  const progressFollowup =
    (pendingFollowup && progressCue) ||
    (progressCue && (followupCue || taskCue)) ||
    (followupCue && taskCue);
  const active = explicit || progressFollowup || (depleted && (agencyAsk || Boolean(flags?.isVenting)));
  let reason = "none";
  if (explicit) reason = "explicit_motivation_request";
  else if (progressFollowup) reason = "motivation_followup_pending";
  else if (depleted && agencyAsk) reason = "depleted_with_agency_request";
  else if (depleted && Boolean(flags?.isVenting)) reason = "depleted_venting_signal";
  return {
    active,
    explicit,
    depleted,
    progressFollowup,
    reason,
  };
}

