function normalizeScreenplayPhaseValue(value) {
  return normalizeSnippet(value, 48) || "scene_draft";
}

function reconcileScreenplayOutline(outline, now = Date.now()) {
  const safeOutline = outline && typeof outline === "object" ? outline : createEmptyScreenplayOutline();
  safeOutline.acts = (Array.isArray(safeOutline.acts) ? safeOutline.acts : [])
    .sort((a, b) => Number(a.order || 0) - Number(b.order || 0))
    .map((act, index) => ({
      ...act,
      order: Math.max(0, Number(act.order ?? index)),
      updatedAt: Math.max(0, Number(act.updatedAt || act.createdAt || now)),
      createdAt: Math.max(0, Number(act.createdAt || act.updatedAt || now)),
    }));
  safeOutline.scenes = (Array.isArray(safeOutline.scenes) ? safeOutline.scenes : [])
    .sort((a, b) => Number(a.order || 0) - Number(b.order || 0))
    .map((scene, index) => ({
      ...scene,
      order: Math.max(0, Number(scene.order ?? index)),
      beatIds: Array.isArray(scene.beatIds) ? scene.beatIds : [],
      updatedAt: Math.max(0, Number(scene.updatedAt || scene.createdAt || now)),
      createdAt: Math.max(0, Number(scene.createdAt || scene.updatedAt || now)),
    }));
  safeOutline.beats = (Array.isArray(safeOutline.beats) ? safeOutline.beats : [])
    .sort((a, b) => Number(a.order || 0) - Number(b.order || 0))
    .map((beat, index) => ({
      ...beat,
      order: Math.max(0, Number(beat.order ?? index)),
      updatedAt: Math.max(0, Number(beat.updatedAt || beat.createdAt || now)),
      createdAt: Math.max(0, Number(beat.createdAt || beat.updatedAt || now)),
    }));
  safeOutline.acts = safeOutline.acts.map((act) => ({
    ...act,
    sceneIds: safeOutline.scenes
      .filter((scene) => String(scene.actId || "") === act.id)
      .sort((a, b) => Number(a.order || 0) - Number(b.order || 0))
      .map((scene) => scene.id),
  }));
  safeOutline.scenes = safeOutline.scenes.map((scene) => ({
    ...scene,
    beatIds: safeOutline.beats
      .filter((beat) => String(beat.sceneId || "") === scene.id)
      .sort((a, b) => Number(a.order || 0) - Number(b.order || 0))
      .map((beat) => beat.id),
  }));
  safeOutline.updatedAt = Math.max(0, Number(safeOutline.updatedAt || now));
  return safeOutline;
}

function parseScreenplayOutlineInput(body, now = Date.now()) {
  const acts = Array.isArray(body?.acts)
    ? body.acts.map((item, index) => normalizeStoredScreenplayAct(item, index)).filter(Boolean)
    : [];
  const scenes = Array.isArray(body?.scenes)
    ? body.scenes.map((item, index) => normalizeStoredScreenplayScene(item, index)).filter(Boolean)
    : [];
  const beats = Array.isArray(body?.beats)
    ? body.beats.map((item, index) => normalizeStoredScreenplayBeat(item, index)).filter(Boolean)
    : [];
  return reconcileScreenplayOutline({
    updatedAt: now,
    acts,
    scenes,
    beats,
  }, now);
}

function upsertScreenplaySceneRecord(project, sceneInput, now = Date.now()) {
  const outline = ensureScreenplayOutline(project);
  const normalized = normalizeStoredScreenplayScene(
    {
      ...sceneInput,
      id: sceneInput?.id || createScreenplayId("scene"),
      createdAt: sceneInput?.createdAt || now,
      updatedAt: now,
    },
    outline.scenes.length
  );
  if (!normalized) return null;
  const existingIndex = outline.scenes.findIndex((scene) => scene.id === normalized.id);
  if (existingIndex >= 0) {
    outline.scenes[existingIndex] = {
      ...outline.scenes[existingIndex],
      ...normalized,
      createdAt: outline.scenes[existingIndex].createdAt || now,
      updatedAt: now,
    };
  } else {
    outline.scenes.push(normalized);
  }
  outline.updatedAt = now;
  project.outline = reconcileScreenplayOutline(outline, now);
  project.updatedAt = now;
  return project.outline.scenes.find((scene) => scene.id === normalized.id) || normalized;
}

function upsertScreenplayBeatRecord(project, beatInput, now = Date.now()) {
  const outline = ensureScreenplayOutline(project);
  const normalized = normalizeStoredScreenplayBeat(
    {
      ...beatInput,
      id: beatInput?.id || createScreenplayId("beat"),
      createdAt: beatInput?.createdAt || now,
      updatedAt: now,
    },
    outline.beats.length
  );
  if (!normalized) return null;
  const existingIndex = outline.beats.findIndex((beat) => beat.id === normalized.id);
  if (existingIndex >= 0) {
    outline.beats[existingIndex] = {
      ...outline.beats[existingIndex],
      ...normalized,
      createdAt: outline.beats[existingIndex].createdAt || now,
      updatedAt: now,
    };
  } else {
    outline.beats.push(normalized);
  }
  outline.updatedAt = now;
  project.outline = reconcileScreenplayOutline(outline, now);
  project.updatedAt = now;
  return project.outline.beats.find((beat) => beat.id === normalized.id) || normalized;
}

function buildScreenplayRevisionPayload(baseDraft, draft, revisionColor = "blue") {
  const baseLines = splitScreenplayLines(baseDraft);
  const nextLines = splitScreenplayLines(draft);
  const maxLines = Math.max(baseLines.length, nextLines.length);
  const ranges = [];
  const summary = {
    unchanged: 0,
    revised: 0,
    added: 0,
    moved: 0,
    removed: 0,
  };

  let currentStatus = "";
  let rangeStart = 1;
  const pushRange = (endLine) => {
    if (!currentStatus) return;
    ranges.push({
      start_line: rangeStart,
      end_line: endLine,
      status: currentStatus,
      color: currentStatus === "unchanged" ? "clear" : revisionColor,
    });
  };

  for (let index = 0; index < maxLines; index += 1) {
    const baseLine = String(baseLines[index] || "");
    const nextLine = String(nextLines[index] || "");
    let status = "unchanged";
    if (!baseLine && nextLine) {
      status = "added";
      summary.added += 1;
    } else if (baseLine && !nextLine) {
      status = "removed";
      summary.removed += 1;
    } else if (baseLine === nextLine) {
      status = "unchanged";
      summary.unchanged += 1;
    } else {
      status = "revised";
      summary.revised += 1;
    }

    if (index >= nextLines.length) {
      continue;
    }
    if (currentStatus && status !== currentStatus) {
      pushRange(index);
      rangeStart = index + 1;
    }
    currentStatus = status;
  }
  pushRange(Math.max(1, nextLines.length));

  return {
    stage: "screenplay_revision",
    mode: "computed",
    revision_color: revisionColor,
    line_count: nextLines.length,
    base_line_count: baseLines.length,
    summary,
    ranges,
  };
}

function escapeXmlText(value) {
  return String(value || "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&apos;");
}

